window.__WORDS__ = {"updated": "2026-09-24", "total": 105, "words": [{"word": "truss", "phonetic": "/trʌs/", "meaning": "n. 桁架（由杆件组成的三角形单元结构，常用于屋架、桥梁、空间结构）；v. 捆绑、缚紧", "collocation": "roof truss（屋架）· space truss（空间桁架）· steel truss（钢桁架）", "examples": [{"en": "The roof of the workshop is supported by 30-meter steel trusses.", "zh": "车间屋顶由 30 米跨度的钢桁架支撑。", "audio": "audio/ex/truss-1.mp3"}, {"en": "We can offer both H-beam frames and truss solutions depending on the span.", "zh": "根据跨度，我们可以提供 H 型钢框架或桁架两种方案。", "audio": "audio/ex/truss-2.mp3"}], "mnemonic": "truss 中间藏着 us（我们）——\"我们\"的厂房靠 truss 撑起来；再看它只比 trust（信任）少一个 t——桁架正是最值得\"信任\"的三角形稳定结构。", "issue": 1, "date": "2026-09-02", "theme": "钢结构与外贸场景核心词 · 首期从最常用的工程/外贸高频词开始", "gloss": "桁架", "category": "钢结构", "audio": "audio/truss.mp3"}, {"word": "fabrication", "phonetic": "/ˌfæbrɪˈkeɪʃn/", "meaning": "n. 制造、（钢构件）预制加工；（另一义）捏造、编造", "collocation": "steel fabrication（钢结构加工）· fabrication workshop（加工车间）· fabrication drawing（深化加工图）", "examples": [{"en": "The fabrication of all steel components will be finished in our factory before container shipping.", "zh": "所有钢构件将在我方工厂完成预制加工后再装箱发运。", "audio": "audio/ex/fabrication-1.mp3"}, {"en": "The client asked us to shorten the fabrication period by two weeks.", "zh": "客户要求我们把加工周期缩短两周。", "audio": "audio/ex/fabrication-2.mp3"}], "mnemonic": "词根 fabric（织物、工厂）+ -ation → 在工厂里把钢材像织布一样\"编织成型\" → 加工制造。外贸邮件里它常和 delivery 成对出现：fabrication & delivery（加工与交货）。", "issue": 1, "date": "2026-09-02", "theme": "钢结构与外贸场景核心词 · 首期从最常用的工程/外贸高频词开始", "gloss": "加工制造；预制", "category": "钢结构", "audio": "audio/fabrication.mp3"}, {"word": "tolerance", "phonetic": "/ˈtɒlərəns/", "meaning": "n. 公差（允许的尺寸偏差）；容忍、宽容（职场引申义）", "collocation": "dimensional tolerance（尺寸公差）· within tolerance（在公差范围内）· zero tolerance（零容忍）", "examples": [{"en": "The dimensional tolerance for this beam is ±2 mm.", "zh": "这根梁的尺寸公差为正负 2 毫米。", "audio": "audio/ex/tolerance-1.mp3"}, {"en": "A good project manager shows zero tolerance for safety violations.", "zh": "优秀的项目经理对安全违规零容忍。", "audio": "audio/ex/tolerance-2.mp3"}], "mnemonic": "一词两义都围绕\"容许的范围\"——对人是\"容忍\"，对尺寸是\"公差\"。记住搭配 zero tolerance（零容忍），两层意思一次锁定。", "issue": 1, "date": "2026-09-02", "theme": "钢结构与外贸场景核心词 · 首期从最常用的工程/外贸高频词开始", "gloss": "公差；容忍", "category": "工程设计", "audio": "audio/tolerance.mp3"}, {"word": "quotation", "phonetic": "/kwəʊˈteɪʃn/", "meaning": "n. 报价、报价单；引文、引用", "collocation": "send/submit a quotation（提交报价）· quotation validity（报价有效期）· formal quotation（正式报价单）", "examples": [{"en": "Could you send us a formal quotation including freight and installation costs?", "zh": "能否发我们一份含运费和安装费的正式报价单？", "audio": "audio/ex/quotation-1.mp3"}, {"en": "This quotation is valid for 30 days from the date of issue.", "zh": "本报价自开立之日起 30 天内有效。", "audio": "audio/ex/quotation-2.mp3"}], "mnemonic": "动词 quote 本义是\"引用别人的话\" → 把价格\"引\"出来写在单子上就是\"报价\"。客户邮件里常简写成 quote——\"What's your quote?\" 就是在问你要报价。", "issue": 1, "date": "2026-09-02", "theme": "钢结构与外贸场景核心词 · 首期从最常用的工程/外贸高频词开始", "gloss": "报价（单）", "category": "外贸", "audio": "audio/quotation.mp3"}, {"word": "itinerary", "phonetic": "/aɪˈtɪnərəri/", "meaning": "n. 行程、旅行日程安排", "collocation": "a detailed itinerary（详细行程）· attached itinerary（附件行程单）· business itinerary（商务行程）", "examples": [{"en": "We've prepared a three-day itinerary for the client's factory visit, including a tour of our fabrication workshop.", "zh": "我们为客户来访准备了三日行程，包括加工车间参观。", "audio": "audio/ex/itinerary-1.mp3"}, {"en": "Please find the itinerary attached and let us know if any adjustment is needed.", "zh": "行程见附件，如需调整请告知。", "audio": "audio/ex/itinerary-2.mp3"}], "mnemonic": "拆成 it-iner-ary——词根 it 表示\"走\"（exit 出口、transit 通行同源）→ 一路\"走\"过之地的清单 → 行程。接待客户前发一句 \"Please find the attached itinerary\" 是标准动作。", "issue": 1, "date": "2026-09-02", "theme": "钢结构与外贸场景核心词 · 首期从最常用的工程/外贸高频词开始", "gloss": "行程；日程安排", "category": "客户接待", "audio": "audio/itinerary.mp3"}, {"word": "purlin", "phonetic": "/ˈpɜːlɪn/", "meaning": "n. 檩条（架在屋架或梁上、直接承托屋面板的水平构件）", "collocation": "C/Z purlin（C 型/Z 型檩条）· purlin spacing（檩条间距）· roll-formed purlin（辊压成型檩条）", "examples": [{"en": "The purlin spacing should be adjusted to match the sheet profile.", "zh": "檩条间距应调整至与屋面板型匹配。", "audio": "audio/ex/purlin-1.mp3"}, {"en": "All C purlins are galvanized and delivered in 6-meter lengths.", "zh": "所有 C 型檩条均为镀锌件，按 6 米定尺交付。", "audio": "audio/ex/purlin-2.mp3"}], "mnemonic": "发音像\"泼淋\"——屋面上\"泼\"下来的雨水，全靠 purlin 上面的板材\"淋\"不进去；和它成对出现的兄弟词是 rafter（椽条），一个水平一个斜放。", "issue": 2, "date": "2026-09-03", "theme": "从构件细节到商务接待 · 钢结构 / 工程 / 建筑设计 / 外贸 / 客户接待各选一词", "gloss": "檩条", "category": "钢结构", "audio": "audio/purlin.mp3"}, {"word": "galvanize", "phonetic": "/ˈɡælvənaɪz/", "meaning": "v. 镀锌（对钢材做防腐处理）；（引申义）激励、使振奋", "collocation": "hot-dip galvanized（热浸镀锌）· galvanized steel coil（镀锌钢卷）· galvanizing thickness（镀锌层厚度，常以 g/m² 或 μm 计）", "examples": [{"en": "All structural members are hot-dip galvanized for coastal projects in Africa.", "zh": "非洲沿海项目的全部结构件均采用热浸镀锌处理。", "audio": "audio/ex/galvanize-1.mp3"}, {"en": "The urgent deadline galvanized the whole team into action.", "zh": "紧迫的工期让整个团队立即行动起来。", "audio": "audio/ex/galvanize-2.mp3"}], "mnemonic": "词根 galvan- 来自电学先驱伽伐尼（Galvani）——最初镀锌靠电镀，所以\"镀锌\"和\"电击般的激励\"共用一个词。报出 \"hot-dip galvanized\" 就等于告诉客户：这钢材能扛海边的高盐雾。", "issue": 2, "date": "2026-09-03", "theme": "从构件细节到商务接待 · 钢结构 / 工程 / 建筑设计 / 外贸 / 客户接待各选一词", "gloss": "镀锌", "category": "钢结构", "audio": "audio/galvanize.mp3"}, {"word": "elevation", "phonetic": "/ˌelɪˈveɪʃn/", "meaning": "n. 立面图（建筑设计的正/侧视图）；标高、海拔高度", "collocation": "front/side elevation（正立面/侧立面图）· elevation drawing（立面图）· finished floor elevation（完成面标高，缩写 F.F.E.）", "examples": [{"en": "Please refer to the south elevation for the cladding color scheme.", "zh": "围护板颜色方案请参见南立面图。", "audio": "audio/ex/elevation-1.mp3"}, {"en": "The site elevation is 1,200 meters above sea level, which affects the wind load parameters.", "zh": "场地标高为海拔 1200 米，会影响风荷载参数取值。", "audio": "audio/ex/elevation-2.mp3"}], "mnemonic": "词根是 elevate（升高）——\"升\"起视线看到的是房子的脸（立面图），\"升\"起的高度就是标高。图纸目录里它总和平面图 plan、剖面图 section 并肩出现：plan / elevation / section 三件套。", "issue": 2, "date": "2026-09-03", "theme": "从构件细节到商务接待 · 钢结构 / 工程 / 建筑设计 / 外贸 / 客户接待各选一词", "gloss": "立面图；标高", "category": "工程设计", "audio": "audio/elevation.mp3"}, {"word": "lead time", "phonetic": "/ˈliːd taɪm/", "meaning": "n. 交货期、生产周期（从下单到交付所需的时间）", "collocation": "production lead time（生产周期）· lead time of 45 days（45 天交货期）· shorten the lead time（压缩交期）", "examples": [{"en": "Our standard lead time is 45 days after receipt of the deposit.", "zh": "收到定金后，我们的标准交货期为 45 天。", "audio": "audio/ex/lead-time-1.mp3"}, {"en": "The client asked if we could shorten the lead time to catch the rainy season schedule.", "zh": "客户询问能否压缩交期，以赶在雨季前完工。", "audio": "audio/ex/lead-time-2.mp3"}], "mnemonic": "lead 是\"领先\"，time 是\"时间\"——从下单那天起就\"领先\"排产、一路领跑的时间段，就是 lead time。外贸谈判三大高频问句之一：What's the price? What's the quality? What's the lead time?", "issue": 2, "date": "2026-09-03", "theme": "从构件细节到商务接待 · 钢结构 / 工程 / 建筑设计 / 外贸 / 客户接待各选一词", "gloss": "交货期；生产周期", "category": "外贸", "audio": "audio/lead-time.mp3"}, {"word": "courtesy", "phonetic": "/ˈkɜːtəsi/", "meaning": "n. 礼遇、礼貌谦恭；（商务语境）出于好意的 complimentary 免费提供/礼节性安排", "collocation": "courtesy call（礼节性拜访/回访）· courtesy car（免费接送车）· as a courtesy（作为礼遇）· return the courtesy（回礼）", "examples": [{"en": "We made a courtesy call on the client at their hotel before the factory tour.", "zh": "工厂参观前，我们到客户下榻酒店做了一次礼节性拜访。", "audio": "audio/ex/courtesy-1.mp3"}, {"en": "As a courtesy, we arranged airport pick-up and a bilingual interpreter for the delegation.", "zh": "作为礼遇，我们为代表团安排了机场接机和双语翻译。", "audio": "audio/ex/courtesy-2.mp3"}], "mnemonic": "和 court（宫廷）同源——宫廷里的人举手投足都讲究礼数。接待海外客户时记住三件套：courtesy call（礼节性拜访）+ courtesy car（接机车）+ courtesy room（免费茶歇室），礼数到位，订单不愁。", "issue": 2, "date": "2026-09-03", "theme": "从构件细节到商务接待 · 钢结构 / 工程 / 建筑设计 / 外贸 / 客户接待各选一词", "gloss": "礼遇；礼貌", "category": "客户接待", "audio": "audio/courtesy.mp3"}, {"word": "bracing", "phonetic": "/ˈbreɪsɪŋ/", "meaning": "n. 支撑、斜撑（钢结构中的抗侧力构件）；v. brace 的现在分词，意为\"支撑住、使稳固\"", "collocation": "", "examples": [{"en": "Cross bracing is required to resist lateral wind loads on the warehouse.", "zh": "需要设置交叉支撑来抵抗仓库的侧向风荷载。", "audio": "audio/ex/bracing-1.mp3"}, {"en": "The engineer braced the temporary column before pouring concrete.", "zh": "工程师在浇筑混凝土前对临时柱进行了加固。", "audio": "audio/ex/bracing-2.mp3"}], "mnemonic": "brace 源自法语\"手臂\"（bras）——像伸出两只手臂把结构\"撑住\"。想想健身房里的护腕（wrist brace），本质都是\"支撑、加固\"。", "issue": 3, "date": "2026-09-04", "theme": "", "gloss": "支撑；斜撑", "category": "钢结构", "audio": "audio/bracing.mp3"}, {"word": "cantilever", "phonetic": "/ˈkæntɪliːvər/", "meaning": "n. 悬臂、悬梁（一端固定、另一端悬空的构件）", "collocation": "", "examples": [{"en": "The canopy is supported by a 3-meter steel cantilever.", "zh": "雨篷由一根 3 米长的钢悬臂支撑。", "audio": "audio/ex/cantilever-1.mp3"}, {"en": "Cantilever beams experience maximum bending moment at the fixed end.", "zh": "悬臂梁的最大弯矩出现在固定端。", "audio": "audio/ex/cantilever-2.mp3"}], "mnemonic": "拆成 can + ti + lever（杠杆）——\"能像杠杆一样挑出去\"。跳水板就是最经典的 cantilever：一端固定，一端悬空。", "issue": 3, "date": "2026-09-04", "theme": "", "gloss": "悬臂", "category": "工程设计", "audio": "audio/cantilever.mp3"}, {"word": "deposit", "phonetic": "/dɪˈpɑːzɪt/", "meaning": "n. 定金、押金、存款；v. 支付定金、存放", "collocation": "", "examples": [{"en": "Please arrange a 30% deposit so we can start fabrication.", "zh": "请安排 30% 的定金，以便我们开始加工生产。", "audio": "audio/ex/deposit-1.mp3"}, {"en": "The hotel requires a deposit for the meeting room booking.", "zh": "酒店要求为会议室预订支付押金。", "audio": "audio/ex/deposit-2.mp3"}], "mnemonic": "de-（向下）+ posit（放置）= \"放下去\"的钱。同根词：position（位置）。钱\"放\"在对方那里作担保，就是 deposit。", "issue": 3, "date": "2026-09-04", "theme": "", "gloss": "定金；押金", "category": "外贸", "audio": "audio/deposit.mp3"}, {"word": "hospitality", "phonetic": "/ˌhɑːspɪˈtæləti/", "meaning": "n. 殷勤款待、接待礼仪（商务接待高频词）", "collocation": "", "examples": [{"en": "Thank you for your hospitality during our factory visit.", "zh": "感谢您在我们参观工厂期间的盛情接待。", "audio": "audio/ex/hospitality-1.mp3"}, {"en": "We'll arrange the hospitality suite for the client's stay.", "zh": "我们会为客户安排商务接待套房。", "audio": "audio/ex/hospitality-2.mp3"}], "mnemonic": "词根 host（主人）——hospitality 就是\"主人对客人的好\"。酒店业 = hospitality industry，记住\"住酒店被款待\"这个场景就忘不掉了。", "issue": 3, "date": "2026-09-04", "theme": "", "gloss": "接待款待", "category": "客户接待", "audio": "audio/hospitality.mp3"}, {"word": "workload", "phonetic": "/ˈwɜːrkloʊd/", "meaning": "n. 工作量、工作负荷", "collocation": "", "examples": [{"en": "My workload doubles during the bidding season.", "zh": "投标季我的工作量翻倍。", "audio": "audio/ex/workload-1.mp3"}, {"en": "We redistributed the workload to meet the submission deadline.", "zh": "我们重新分配了工作量，以确保按期提交。", "audio": "audio/ex/workload-2.mp3"}], "mnemonic": "work + load（荷载）——工程师秒懂：结构有荷载，人有 workload，超载都会\"垮\"。可以自嘲一句 \"My workload is over-designed.\"", "issue": 3, "date": "2026-09-04", "theme": "", "gloss": "工作量", "category": "职场", "audio": "audio/workload.mp3"}, {"word": "gusset", "phonetic": "/ˈɡʌsɪt/", "meaning": "n. 节点板、加劲板（钢结构梁柱节点处用于加强连接的多边形钢板）", "collocation": "", "examples": [{"en": "The engineer specified a 10 mm gusset plate at the beam-column joint.", "zh": "工程师在梁柱节点处指定使用 10 mm 厚的节点板。", "audio": "audio/ex/gusset-1.mp3"}, {"en": "All gusset welds must be inspected by UT after fabrication.", "zh": "所有节点板焊缝在加工完成后须进行超声波检测。", "audio": "audio/ex/gusset-2.mp3"}], "mnemonic": "发音像\"嘎塞特\"，联想\"卡塞进去\"——节点板就是塞在梁柱节点里把力\"卡\"住的钢片。再记搭配 gusset plate = node plate = 节点板，三种叫法都是它。", "issue": 4, "date": "2026-09-07", "theme": "", "gloss": "节点板", "category": "钢结构", "audio": "audio/gusset.mp3"}, {"word": "deflection", "phonetic": "/dɪˈflekʃn/", "meaning": "n. 挠度、变形量（结构在荷载作用下产生的竖向或水平位移）", "collocation": "", "examples": [{"en": "The live-load deflection of the main beam shall not exceed L/360.", "zh": "主梁在活载作用下的挠度不得超过 L/360。", "audio": "audio/ex/deflection-1.mp3"}, {"en": "Excessive deflection may indicate inadequate stiffener spacing.", "zh": "过大的挠度可能意味着加劲肋间距不足。", "audio": "audio/ex/deflection-2.mp3"}], "mnemonic": "de-（向下）+ flect（弯曲）= \"向下弯\"的程度。搭配记忆：deflection check（挠度验算）、deflection control（挠度控制）、deflection limit（挠度限值）——工程师一提\"挠度\"基本就这三件事。", "issue": 4, "date": "2026-09-07", "theme": "", "gloss": "挠度；变形量", "category": "工程设计", "audio": "audio/deflection.mp3"}, {"word": "proforma invoice", "phonetic": "/proʊˈfɔːrmə ˈɪnvɔɪs/", "meaning": "n. 形式发票、预开发票（外贸中用于报价、申办签证或申请信用证的临时发票）", "collocation": "", "examples": [{"en": "We'll send you the proforma invoice within 24 hours for your reference.", "zh": "我们将在 24 小时内将形式发票发给您参考。", "audio": "audio/ex/proforma-invoice-1.mp3"}, {"en": "The proforma invoice is required for the buyer's import license application.", "zh": "买方申请进口许可证需要这份形式发票。", "audio": "audio/ex/proforma-invoice-2.mp3"}], "mnemonic": "proforma 源自拉丁语\"为了形式\"——形式发票不是真正能结账的发票，而是\"形式上\"先给客户走流程用的。和 commercial invoice（商业发票）搭配记：一个走\"形式\"，一个走\"货款\"。", "issue": 4, "date": "2026-09-07", "theme": "", "gloss": "形式发票", "category": "外贸", "audio": "audio/proforma-invoice.mp3"}, {"word": "pick-up", "phonetic": "/ˈpɪk ʌp/", "meaning": "n. 接送、接机、取件；v. 接（人/货）、取（物品）", "collocation": "", "examples": [{"en": "Airport pick-up has been booked for 14:00 on the 8th.", "zh": "8 号下午两点已为您安排机场接送。", "audio": "audio/ex/pick-up-1.mp3"}, {"en": "Please confirm the pick-up time and flight number for the client.", "zh": "请确认客户的接送时间和航班号。", "audio": "audio/ex/pick-up-2.mp3"}], "mnemonic": "pick（拣）+ up（起来）= \"把人拣起来带走\"。接待场景高频搭配：airport pick-up（机场接送）、pick-up service（接送服务）、hotel pick-up（酒店接送）。客户接待邮件里出现率几乎 100%。", "issue": 4, "date": "2026-09-07", "theme": "", "gloss": "接送；接机", "category": "客户接待", "audio": "audio/pick-up.mp3"}, {"word": "agenda", "phonetic": "/əˈdʒendə/", "meaning": "n. 议程、待议事项（会议或谈判的主题清单）", "collocation": "", "examples": [{"en": "Let's go through the agenda before we start the kick-off meeting.", "zh": "项目启动会开始前，我们先过一下议程。", "audio": "audio/ex/agenda-1.mp3"}, {"en": "Factory tour is item 3 on the agenda for tomorrow.", "zh": "参观工厂是明天议程的第 3 项。", "audio": "audio/ex/agenda-2.mp3"}], "mnemonic": "复数 agendas。联想\"a + gend（要走）+ a\"——会议就是要\"走\"完的一串事项。搭配记忆：meeting agenda（会议议程）、set the agenda（定议程）、hidden agenda（隐藏议题）。后者在海外项目沟通里尤其要警惕。", "issue": 4, "date": "2026-09-07", "theme": "", "gloss": "议程", "category": "职场", "audio": "audio/agenda.mp3"}, {"word": "flange", "phonetic": "/flændʒ/", "meaning": "H 型钢或工字钢上下凸出的水平部分叫翼缘；管道连接处的圆盘叫法兰。", "collocation": "", "examples": [{"en": "The flange width of the H-section beam must meet the design drawing before fabrication.", "zh": "H 型钢梁的翼缘宽度在加工前必须与设计图纸一致。", "audio": "audio/ex/flange-1.mp3"}], "mnemonic": "谐音\"福兰治\"——想象法兰盘上刻着\"福\"字，连接起来福气满满；H 型钢的\"两横\"就是两片翼缘。", "issue": 5, "date": "2026-09-08", "theme": "集装箱房报价到交付的\"外贸全流程\"", "gloss": "翼缘；法兰", "category": "钢结构", "audio": "audio/flange.mp3"}, {"word": "fastener", "phonetic": "/ˈfɑːsnə(r)/", "meaning": "螺栓、螺钉、铆钉、自攻钉这类连接件的统称，外贸清单里的高频词。", "collocation": "", "examples": [{"en": "All high-strength fasteners for the warehouse project shall be hot-dip galvanized.", "zh": "仓库项目的所有高强度紧固件均须热浸镀锌。", "audio": "audio/ex/fastener-1.mp3"}], "mnemonic": "fasten（固定）+ -er（东西）= 用来固定的东西。记住词根 fasten，一整套家族词（fasten/unfasten）全拿下。", "issue": 5, "date": "2026-09-08", "theme": "集装箱房报价到交付的\"外贸全流程\"", "gloss": "紧固件", "category": "钢结构", "audio": "audio/fastener.mp3"}, {"word": "facade", "phonetic": "/fəˈsɑːd/", "meaning": "建筑的正面/外立面；引申为\"表面功夫、假象\"。", "collocation": "", "examples": [{"en": "The client asked for a glass and steel facade to make the office building look more modern.", "zh": "客户要求采用玻璃+钢结构立面，让办公楼更显现代。", "audio": "audio/ex/facade-1.mp3"}], "mnemonic": "源自法语\"正面\"，谐音\"法萨德\"——法国人最讲究建筑门面。facade 是建筑的\"脸（face）\"， faç ade 里的 ç 就是这张脸的\"酒窝\"。", "issue": 5, "date": "2026-09-08", "theme": "集装箱房报价到交付的\"外贸全流程\"", "gloss": "立面；外观", "category": "工程设计", "audio": "audio/facade.mp3"}, {"word": "freight", "phonetic": "/freɪt/", "meaning": "海运整柜/拼柜、空运货物的统称；也指运费本身，海外项目报价必谈。", "collocation": "", "examples": [{"en": "The CIF price includes ocean freight, but the buyer covers the import duties.", "zh": "CIF 价包含海运费，但进口关税由买方承担。", "audio": "audio/ex/freight-1.mp3"}], "mnemonic": "对比记忆三兄弟——freight（货运/运费）、fee（手续费）、duty（关税）。F 开头的 freight 管\"运\"，D 开头的 duty 管\"税\"。", "issue": 5, "date": "2026-09-08", "theme": "集装箱房报价到交付的\"外贸全流程\"", "gloss": "货运；运费", "category": "外贸", "audio": "audio/freight.mp3"}, {"word": "follow-up", "phonetic": "/ˈfɒləʊ ʌp/", "meaning": "商务沟通中表示\"后续跟进/回访\"，外贸成单全靠它。", "collocation": "", "examples": [{"en": "Thank you for the meeting today — I will send a follow-up email with the revised drawings.", "zh": "感谢今天的会面——我会发一封跟进邮件，附上修改后的图纸。", "audio": "audio/ex/follow-up-1.mp3"}], "mnemonic": "follow（跟随）+ up（向上）= 把事情\"往上追\"。记住固定句式 \"Just following up on...\"（跟进一下之前说的……），催单催图都好用。", "issue": 5, "date": "2026-09-08", "theme": "集装箱房报价到交付的\"外贸全流程\"", "gloss": "跟进；后续", "category": "外贸", "audio": "audio/follow-up.mp3"}, {"word": "anchor bolt", "phonetic": "/ˈæŋkə(r) bəʊlt/", "meaning": "把钢柱固定在混凝土基础上的螺栓，预埋位置一旦出错，整根柱子都装不上。", "collocation": "", "examples": [{"en": "The anchor bolts must be embedded in the foundation exactly according to the setting-out drawing.", "zh": "地脚螺栓必须严格按照放样图预埋在基础中。", "audio": "audio/ex/anchor-bolt-1.mp3"}], "mnemonic": "anchor（锚）+ bolt（螺栓）= 像\"锚\"一样把柱子锚固在基础里的螺栓。想象船锚扎进海底——anchor bolt 扎进混凝土。", "issue": 6, "date": "2026-09-09", "theme": "海外项目从图纸到现场安装", "gloss": "地脚螺栓；锚栓", "category": "钢结构", "audio": "audio/anchor-bolt.mp3"}, {"word": "erection", "phonetic": "/ɪˈrekʃn/", "meaning": "钢结构行业里 erection 不是医学词，专指\"现场拼装、吊装成型\"，图纸上的 ERECT ON SITE 就是\"现场拼装\"。", "collocation": "", "examples": [{"en": "The erection of the steel frame will take about two weeks after all materials arrive on site.", "zh": "材料全部到场后，钢框架的现场安装大约需要两周。", "audio": "audio/ex/erection-1.mp3"}], "mnemonic": "词根 erect（竖立）——把躺着的构件\"竖起来\"就是 erection。钢构行业缩写送你一个：E.O.S. = Erect On Site（现场拼装）。", "issue": 6, "date": "2026-09-09", "theme": "海外项目从图纸到现场安装", "gloss": "安装；吊装", "category": "钢结构", "audio": "audio/erection.mp3"}, {"word": "layout", "phonetic": "/ˈleɪaʊt/", "meaning": "总平面/平面布置方案，售楼、厂房规划、板房排布都绕不开它；引申为\"版面设计\"。", "collocation": "", "examples": [{"en": "We prepared three options for the camp layout so the client can compare the room arrangements.", "zh": "我们准备了三个营地平面布置方案，供客户比较房间排布。", "audio": "audio/ex/layout-1.mp3"}], "mnemonic": "lay（放置）+ out（摊开）= 把所有房间\"摊开摆好\"。设计师口头禅 \"Let me show you the layout\"（我给你看下平面布置）。", "issue": 6, "date": "2026-09-09", "theme": "海外项目从图纸到现场安装", "gloss": "布局；平面布置", "category": "建筑设计", "audio": "audio/layout.mp3"}, {"word": "shipment", "phonetic": "/ˈʃɪpmənt/", "meaning": "一批货物从工厂发运出口；邮件里 \"first shipment\" 指首批发货，常和 container 搭配。", "collocation": "", "examples": [{"en": "The first shipment of containers will leave Qingdao Port next Monday.", "zh": "首批集装箱货将于下周一从青岛港发出。", "audio": "audio/ex/shipment-1.mp3"}], "mnemonic": "ship（船运）+ -ment（名词后缀）= 装船发出的一批货。三个兄弟词分清：shipment（发货/一批货）、shipping（运输业/运输方式）、shipper（发货人）。", "issue": 6, "date": "2026-09-09", "theme": "海外项目从图纸到现场安装", "gloss": "发货；装运", "category": "外贸", "audio": "audio/shipment.mp3"}, {"word": "overtime", "phonetic": "/ˈəʊvətaɪm/", "meaning": "正常工时之外的工作时间；口语 \"work overtime\" 就是加班，报价谈判里也涉及工地的 overtime cost（加班费）。", "collocation": "", "examples": [{"en": "To catch the shipment deadline, our workshop worked overtime for the whole week.", "zh": "为了赶上发货期限，我们车间整整加了一周的班。", "audio": "audio/ex/overtime-1.mp3"}], "mnemonic": "over（超过）+ time（时间）= 超出正常时间。体育解说里 overtime 是\"加时赛\"——上班族的\"加时赛\"就是加班。", "issue": 6, "date": "2026-09-09", "theme": "海外项目从图纸到现场安装", "gloss": "加班；加班时间", "category": "职场", "audio": "audio/overtime.mp3"}, {"word": "weld", "phonetic": "/weld/", "meaning": "用加热使金属熔合的工艺或连接点；在钢构里焊缝质量直接决定结构安全，是现场和车间都跳不开的工序。", "collocation": "weld seam 焊缝；field weld 现场焊；butt weld 对接焊缝；fillet weld 角焊缝；weld inspection 焊缝检测", "examples": [{"en": "Every weld seam must pass visual inspection, and 20% of them require ultrasonic testing.", "zh": "每条焊缝都必须通过目检，其中 20% 需做超声波探伤。", "audio": "audio/ex/weld-1.mp3"}], "mnemonic": "谐音\"外的\"——想象把两块钢板\"焊在一起变成一块\"，从\"外\"看不到缝就是焊好了。well done 的 well 换成 weld，听着就像焊工师傅的口头禅。", "issue": 7, "date": "2026-09-10", "theme": "客户来访技术澄清 → 焊接质量控制 → 海运清关交付", "gloss": "焊接；焊缝", "category": "钢结构", "audio": "audio/weld.mp3"}, {"word": "stiffener", "phonetic": "/ˈstɪfnər/", "meaning": "焊在钢梁腹板上防止薄板受压失稳的小钢板，是吊车梁、平台梁设计里绕不开的细件。", "collocation": "web stiffener 腹板加劲肋；bearing stiffener 支承加劲肋；intermediate stiffener 中间加劲肋；transverse stiffener 横向加劲肋", "examples": [{"en": "Please add two web stiffeners on each side of the beam under the heavy crane rail.", "zh": "重级吊车梁下翼缘两侧请各加两块腹板加劲肋。", "audio": "audio/ex/stiffener-1.mp3"}], "mnemonic": "stiffen（变刚、变硬）+ -er（名词后缀）= 让钢板\"变刚\"的零件。stiff = 僵硬，加 -ener 就是\"让东西变僵硬的那个件\"。", "issue": 7, "date": "2026-09-10", "theme": "客户来访技术澄清 → 焊接质量控制 → 海运清关交付", "gloss": "加劲肋；加强件", "category": "钢结构", "audio": "audio/stiffener.mp3"}, {"word": "staircase", "phonetic": "/ˈsteəkeɪs/", "meaning": "建筑物内从一层通往另一层的整套构件，包括踏步、栏杆、平台和井道；标准化安置房和集装箱房方案里都要排进立面图。", "collocation": "external staircase 室外楼梯；fire staircase 消防楼梯；prefabricated staircase 预制楼梯；spiral staircase 旋转楼梯", "examples": [{"en": "We chose a prefabricated steel staircase to shorten the on-site assembly time.", "zh": "我们选了预制钢楼梯以缩短现场拼装时间。", "audio": "audio/ex/staircase-1.mp3"}], "mnemonic": "stair（踏步）+ case（围合空间）= \"把踏步围起来的那段建筑\"就是整段楼梯。和 stair（一步）、stairway（楼梯通道）、elevator（电梯）区分用。", "issue": 7, "date": "2026-09-10", "theme": "客户来访技术澄清 → 焊接质量控制 → 海运清关交付", "gloss": "楼梯", "category": "建筑设计", "audio": "audio/staircase.mp3"}, {"word": "customs clearance", "phonetic": "/ˈkʌstəmz ˈklɪrəns/", "meaning": "货物进出境时在海关办理申报、缴税、查验、放行的全过程；从集装箱到港到客户仓库最重要的\"最后一道关\"。", "collocation": "customs declaration 报关单；customs duty 关税；clear customs 通过海关；customs broker 报关行；delayed at customs 卡在海关", "examples": [{"en": "The containers were delayed at customs because the packing list did not match the commercial invoice.", "zh": "集装箱卡在海关了，因为装箱单和商业发票对不上。", "audio": "audio/ex/customs-clearance-1.mp3"}], "mnemonic": "customs（海关）+ clearance（清空、放行）= \"海关那边给你放行\"就叫清关。外贸高频词，单子对不上 = delayed at customs。", "issue": 7, "date": "2026-09-10", "theme": "客户来访技术澄清 → 焊接质量控制 → 海运清关交付", "gloss": "清关", "category": "外贸", "audio": "audio/customs-clearance.mp3"}, {"word": "clarification", "phonetic": "/ˌklærɪfɪˈkeɪʃn/", "meaning": "把模糊、有歧义的事项讲清楚；客户来访开技术交底会最常说的就是 \"We need clarification on...\"", "collocation": "seek clarification 请求澄清；ask for clarification 请求说明；technical clarification 技术澄清；for clarification 为了说清楚", "examples": [{"en": "The client raised three technical clarifications during the kick-off meeting yesterday.", "zh": "昨天的项目启动会上，客户提出了三项技术澄清。", "audio": "audio/ex/clarification-1.mp3"}], "mnemonic": "动词 clarify（澄清）+ -ation（名词后缀）= clarification。客户邮件里 \"for clarification\" = \"我再补充说明一下\"，别理解成\"为了清楚起见\"那么死板。", "issue": 7, "date": "2026-09-10", "theme": "客户来访技术澄清 → 焊接质量控制 → 海运清关交付", "gloss": "澄清；说明", "category": "客户接待", "audio": "audio/clarification.mp3"}, {"word": "portal frame", "phonetic": "/ˈpɔːtl freɪm/", "meaning": "由柱和梁刚性连接组成的单层钢结构体系，是厂房、仓库、安置房最常见的结构形式；跨度大、施工快、造价低。", "collocation": "steel portal frame 钢门式刚架；portal frame building 门式刚架建筑；rigid frame connection 刚接节点；portal frame span 刚架跨度", "examples": [{"en": "The warehouse is designed as a steel portal frame with a clear span of 30 meters.", "zh": "这座仓库设计为钢门式刚架结构，净跨 30 米。", "audio": "audio/ex/portal-frame-1.mp3"}], "mnemonic": "portal（大门、入口）+ frame（框架）= \"像大门洞一样敞开的大框架\"，中间没有柱子挡路，所以最适合大跨度厂房。想象厂房大门一开就是一榀刚架。", "issue": 8, "date": "2026-09-11", "theme": "客户来厂考察 → 门式刚架方案定跨度 → AI 效果图出图 → 信用证收汇", "gloss": "门式刚架", "category": "钢结构", "audio": "audio/portal-frame.mp3"}, {"word": "span", "phonetic": "/spæn/", "meaning": "结构上两支承点之间的水平距离；钢结构报价和设计里第一个要问的数字，span 直接决定梁高、用钢量和造价。", "collocation": "clear span 净跨；column span 柱距；span length 跨长；single span 单跨；multiple span 多跨", "examples": [{"en": "If we increase the span from 24 to 30 meters, the steel weight per square meter will rise by about 15%.", "zh": "如果把跨度从 24 米加大到 30 米，每平方米用钢量会增加约 15%。", "audio": "audio/ex/span-1.mp3"}], "mnemonic": "span 的本义是\"张开大拇指到小指的跨度\"，也就是一拃。桥梁英文 bridge span = 桥的\"一拃\"。设计沟通时张手比划跨度，说的就是这个词。", "issue": 8, "date": "2026-09-11", "theme": "客户来厂考察 → 门式刚架方案定跨度 → AI 效果图出图 → 信用证收汇", "gloss": "跨度", "category": "工程设计", "audio": "audio/span.mp3"}, {"word": "rendering", "phonetic": "/ˈrendərɪŋ/", "meaning": "把三维模型渲染成带光影、材质的逼真图片；建筑方案汇报和 AI 出图时代的核心交付物，客户最先看到的就是它。", "collocation": "architectural rendering 建筑效果图；3D rendering 三维渲染；photorealistic rendering 照片级渲染；interior rendering 室内效果图", "examples": [{"en": "We sent the client three photorealistic renderings of the prefabricated housing scheme before the kick-off meeting.", "zh": "启动会前，我们给客户发了三张预制安置房方案的照片级效果图。", "audio": "audio/ex/rendering-1.mp3"}], "mnemonic": "render（渲染、给出）+ -ing。老外说 \"render an image\" 就像说\"渲染出一张图\"。跟 drawing（线稿图）区分：rendering 有光影材质，drawing 是黑白线条。", "issue": 8, "date": "2026-09-11", "theme": "客户来厂考察 → 门式刚架方案定跨度 → AI 效果图出图 → 信用证收汇", "gloss": "效果图；渲染", "category": "建筑设计", "audio": "audio/rendering.mp3"}, {"word": "letter of credit", "phonetic": "/ˈletər əv ˈkredɪt/", "meaning": "银行应买方申请开出的、承诺凭符合条款的单据付款的保证文件；大宗钢结构出口最常用的付款方式，双方都不认识时靠银行信用兜底。", "collocation": "open an L/C 开信用证；irrevocable letter of credit 不可撤销信用证；sight L/C 即期信用证；L/C at sight 即期信用证；under the L/C 在信用证项下", "examples": [{"en": "We only release the production drawings after receiving the irrevocable letter of credit from the client's bank.", "zh": "收到客户银行开出的不可撤销信用证后，我们才发放生产图纸。", "audio": "audio/ex/letter-of-credit-1.mp3"}], "mnemonic": "letter（信）+ credit（信用）= \"银行写的一封信用担保信\"。外贸缩写 L/C 天天见，记住\"先有 L/C，再动生产\"这条铁律就忘不掉。", "issue": 8, "date": "2026-09-11", "theme": "客户来厂考察 → 门式刚架方案定跨度 → AI 效果图出图 → 信用证收汇", "gloss": "信用证（L/C）", "category": "外贸", "audio": "audio/letter-of-credit.mp3"}, {"word": "site visit", "phonetic": "/saɪt ˈvɪzɪt/", "meaning": "到工厂、工地或项目现场实地查看；海外客户来华验厂、工程师去海外项目巡检都叫 site visit，是建立信任最快的方式。", "collocation": "arrange a site visit 安排现场考察；factory site visit 验厂；site visit report 考察报告；during the site visit 考察期间；pre-construction site visit 施工前踏勘", "examples": [{"en": "The client from Africa will make a site visit to our fabrication plant next Tuesday.", "zh": "非洲客户下周二将来我们加工厂实地考察。", "audio": "audio/ex/site-visit-1.mp3"}], "mnemonic": "site（场地）+ visit（拜访）= \"去场地拜访\"。接待客户三部曲：courtesy call（礼节性电话）→ site visit（现场考察）→ follow-up（后续跟进），visit 是中间那步\"眼见为实\"。", "issue": 8, "date": "2026-09-11", "theme": "客户来厂考察 → 门式刚架方案定跨度 → AI 效果图出图 → 信用证收汇", "gloss": "现场考察；验厂", "category": "客户接待", "audio": "audio/site-visit.mp3"}, {"word": "rafter", "phonetic": "/ˈrɑːftə/", "meaning": "坡屋面中直接支承檩条（purlin）的斜向构件；在门式刚架厂房里也指变截面屋面斜梁，与柱刚性连接组成一榀刚架。", "collocation": "roof rafter 屋面椽条；rafter beam 屋面斜梁；rafter slope 斜梁坡度；common rafter 普通椽条", "examples": [{"en": "The purlins rest on the rafters, which are bolted to the portal frame columns.", "zh": "檩条搁置在椽条上，椽条用螺栓与门式刚架柱连接。", "audio": "audio/ex/rafter-1.mp3"}], "mnemonic": "跟 purlin（檩条）成对记：坡屋面上\"斜着的梁\"是 rafter，\"横着的檩\"是 purlin。rafter 与 roof 同押 r 头韵——roof 的骨架就是 rafter，purlin 横骑在 rafter 背上。", "issue": 9, "date": "2026-09-12", "theme": "施工图定基础与屋面梁 → 构件海运交提单 → 交付庆功设宴", "gloss": "椽条；屋面斜梁", "category": "钢结构", "audio": "audio/rafter.mp3"}, {"word": "foundation", "phonetic": "/faʊnˈdeɪʃn/", "meaning": "把上部结构荷载传给地基的下部结构；钢结构项目里基础尺寸和预埋件（含地脚螺栓）必须在图纸阶段定死，现场返工代价最大。", "collocation": "foundation design 基础设计；foundation plan 基础平面图；pad foundation 独立基础；foundation bolt 基础螺栓；lay the foundation 打基础", "examples": [{"en": "The anchor bolts must be accurately positioned before the concrete foundation is poured.", "zh": "浇筑混凝土基础之前，地脚螺栓必须精准定位。", "audio": "audio/ex/foundation-1.mp3"}], "mnemonic": "found（建立、创立）+ -ation = 建筑\"立起来之前先做的那部分\"。中文\"奠基\"完全对应 lay the foundation；老外说 \"lay a solid foundation for cooperation\"（为合作打下坚实基础），正是从工地走进商务用语的。", "issue": 9, "date": "2026-09-12", "theme": "施工图定基础与屋面梁 → 构件海运交提单 → 交付庆功设宴", "gloss": "基础；地基", "category": "工程设计", "audio": "audio/foundation.mp3"}, {"word": "blueprint", "phonetic": "/ˈbluːprɪnt/", "meaning": "本指晒印出的蓝底白线施工图，如今泛指全套施工图或\"总体规划方案\"；与客户讲 \"as per the blueprint\" 就是在谈按图施工。", "collocation": "construction blueprint 施工蓝图；blueprint drawing 蓝图图纸；a blueprint for... ……的总体规划；as per the blueprint 按蓝图施工", "examples": [{"en": "The fabrication team works strictly as per the approved blueprints.", "zh": "加工团队严格按照已批准的施工图作业。", "audio": "audio/ex/blueprint-1.mp3"}], "mnemonic": "blue（蓝）+ print（印刷）= 晒图机晒出的蓝底白线图。中文\"蓝图\"是直译，还多了层\"宏大愿景\"的意思——向客户讲规划时说 \"our blueprint for the project\"，瞬间自带图纸感。", "issue": 9, "date": "2026-09-12", "theme": "施工图定基础与屋面梁 → 构件海运交提单 → 交付庆功设宴", "gloss": "蓝图；施工图", "category": "建筑设计", "audio": "audio/blueprint.mp3"}, {"word": "bill of lading", "phonetic": "/ˌbɪl əv ˈleɪdɪŋ/", "meaning": "船公司签发的货物收据、运输合同证明与物权凭证\"三合一\"单据；货到港后客户凭正本提单才能提货，也是信用证结汇的核心单据之一。", "collocation": "original bill of lading 正本提单；clean B/L 清洁提单；telex release 电放提单；B/L number 提单号；present the B/L 凭提单提货", "examples": [{"en": "We will courier the original bill of lading to the client once the vessel departs.", "zh": "船一开航，我们就把正本提单快递给客户。", "audio": "audio/ex/bill-of-lading-1.mp3"}], "mnemonic": "bill（单据）+ lade（装载，load 的古体词）= \"货已装船的凭证单\"。三重身份口诀：收货凭证、运输合同、货权在手——\"一单在手，货权我有\"。邮件里天天见缩写 B/L。", "issue": 9, "date": "2026-09-12", "theme": "施工图定基础与屋面梁 → 构件海运交提单 → 交付庆功设宴", "gloss": "提单（B/L）", "category": "外贸", "audio": "audio/bill-of-lading.mp3"}, {"word": "banquet", "phonetic": "/ˈbæŋkwɪt/", "meaning": "正式宴请，通常有座次安排和致辞环节；海外客户来访、项目签约、交货庆功都离不开 banquet，是客户接待的\"压轴戏\"。", "collocation": "welcome banquet 欢迎宴会；celebration banquet 庆功宴；host a banquet 设宴款待；banquet hall 宴会厅；at the farewell banquet 在饯行宴上", "examples": [{"en": "We hosted a farewell banquet for the client at the hotel after the final acceptance.", "zh": "最终验收结束后，我们在酒店为客户设宴饯行。", "audio": "audio/ex/banquet-1.mp3"}], "mnemonic": "跟 bank 没关系——源自法语\"座席、小凳\"。按接待三部曲记：welcome banquet（接风）→ site visit（考察）→ farewell banquet（饯行），有来有送，礼数周全。", "issue": 9, "date": "2026-09-12", "theme": "施工图定基础与屋面梁 → 构件海运交提单 → 交付庆功设宴", "gloss": "宴会；宴请", "category": "客户接待", "audio": "audio/banquet.mp3"}, {"word": "girder", "phonetic": "/ˈɡɜːdə/", "meaning": "结构体系中的主要承重梁，截面大、跨越主要柱距；钢结构厂房里常指支承次梁（secondary beam）的主钢梁，与柱一起构成受力骨架。", "collocation": "crane girder 吊车梁；plate girder 板梁；main girder 主梁；girder connection 主梁连接；composite girder 组合梁", "examples": [{"en": "The crane girders are supported by the portal frame columns on bracket connections.", "zh": "吊车梁通过牛腿连接支承在门式刚架柱上。", "audio": "audio/ex/girder-1.mp3"}], "mnemonic": "girder 谐音\"格得\"——大梁一放，格子（柱网）就\"格\"出来了。跟 beam 分工记：beam 泛指\"梁\"，girder 专指\"挑大梁\"的那根，所以叫\"主梁\"。吊车梁 crane girder 是厂房最常谈到的 girder。", "issue": 10, "date": "2026-09-13", "theme": "技术规范定主梁与墙板 → 价格谈判来回还盘 → 客户来访安排住宿", "gloss": "主梁；大梁", "category": "钢结构", "audio": "audio/girder.mp3"}, {"word": "cladding", "phonetic": "/ˈklædɪŋ/", "meaning": "包在钢结构骨架外面的围护板材（彩钢夹芯板、 corrugated 板等），起保温、防水、美观作用；集装箱房和安置房项目里 cladding 的板型与厚度是报价必谈项。", "collocation": "wall cladding 墙面板；roof and wall cladding 屋面墙面板；cladding panel 围护板；cladding thickness 板材厚度；install the cladding 安装墙板", "examples": [{"en": "The wall cladding is 50mm sandwich panel with both sides pre-painted.", "zh": "墙面板是 50 毫米双面预涂装夹芯板。", "audio": "audio/ex/cladding-1.mp3"}], "mnemonic": "clad（覆盖、穿衣）+ -ding = 给房子\"穿衣服\"。钢结构是骨架（skeleton），cladding 就是外衣——\"bone 立起来，clothes 穿上去\"。跟 facade（第 5 期\"立面\"）区分：facade 讲\"脸面\"，cladding 讲\"板材\"本身。", "issue": 10, "date": "2026-09-13", "theme": "技术规范定主梁与墙板 → 价格谈判来回还盘 → 客户来访安排住宿", "gloss": "围护板；墙面板", "category": "钢结构", "audio": "audio/cladding.mp3"}, {"word": "specification", "phonetic": "/ˌspesɪfɪˈkeɪʃn/", "meaning": "规定材料、工艺、检验标准的技术文件；钢结构项目里 steel grade、coating、welding 都按 specification 执行，与图纸合称 \"drawings and specifications\"。", "collocation": "technical specification 技术规范；material specification 材料规格；as per specification 按规范；spec sheet 规格表；meet the specifications 满足规范要求", "examples": [{"en": "All materials shall be supplied in strict accordance with the technical specifications.", "zh": "所有材料均须严格按技术规范供应。", "audio": "audio/ex/specification-1.mp3"}], "mnemonic": "specify（具体指明）+ -ation = \"写得明明白白的文件\"。工地口头禅 \"as per spec\"（按规范来）天天挂嘴边。记忆一句话：图纸画形状（drawing），spec 定标准（specification）——一个管\"长什么样\"，一个管\"用什么做、做到什么程度\"。", "issue": 10, "date": "2026-09-13", "theme": "技术规范定主梁与墙板 → 价格谈判来回还盘 → 客户来访安排住宿", "gloss": "规格书；技术规范", "category": "工程设计", "audio": "audio/specification.mp3"}, {"word": "counteroffer", "phonetic": "/ˈkaʊntərɒfə/", "meaning": "外贸谈判中对报价（quotation）的回还价：买方嫌贵提出还盘，卖方可接受、拒绝或再还 counter-counteroffer；一来一回就构成价格谈判的回合。", "collocation": "make a counteroffer 还盘；accept/reject the counteroffer 接受/拒绝还盘；a counteroffer of USD 480 还盘 480 美元；counter-counteroffer 反还盘；meet halfway 各让一步", "examples": [{"en": "The buyer made a counteroffer of USD 480 per ton, but our bottom line is 500.", "zh": "买方还盘每吨 480 美元，但我们的底价是 500 美元。", "audio": "audio/ex/counteroffer-1.mp3"}], "mnemonic": "counter-（反、回）+ offer（报价）= \"把价格打回去\"。报价链条记：offer（发盘）→ counteroffer（还盘）→ acceptance（接受）→ contract（成交）。跟已学的 quotation（第 1 期）配对：我先 quotation，你 counteroffer。", "issue": 10, "date": "2026-09-13", "theme": "技术规范定主梁与墙板 → 价格谈判来回还盘 → 客户来访安排住宿", "gloss": "还盘；还价", "category": "外贸", "audio": "audio/counteroffer.mp3"}, {"word": "accommodation", "phonetic": "/əˌkɒməˈdeɪʃn/", "meaning": "给来访客户安排的食宿接待；商务语境里 \"book the accommodation\" 就是订酒店，\"arrange accommodation and transportation\" 是客户接待的标准动作；另有\"迁就、适应\"之义。", "collocation": "book the accommodation 预订住宿；arrange accommodation 安排食宿；business accommodation 商务住宿；accommodation and transportation 食宿与交通；make accommodation for... 为……作出安排", "examples": [{"en": "We will arrange accommodation and airport pick-up for your delegation next week.", "zh": "下周我们将为贵方代表团安排住宿和接机。", "audio": "audio/ex/accommodation-1.mp3"}], "mnemonic": "accommodate = ac- + com- + mod（量、尺度）= \"给足尺度\"——房间给足是\"住宿\"，要求给足是\"迁就\"。接待五件套口诀：itinerary（行程）→ pick-up（接机）→ accommodation（住宿）→ banquet（宴请）→ farewell（送别），三个都已在往期学过，今天就差这一块拼图。", "issue": 10, "date": "2026-09-13", "theme": "技术规范定主梁与墙板 → 价格谈判来回还盘 → 客户来访安排住宿", "gloss": "住宿；接待安排", "category": "客户接待", "audio": "audio/accommodation.mp3"}, {"word": "column", "phonetic": "/ˈkɒləm/", "meaning": "结构中竖向承重构件，把屋面和吊车荷载传到基础；钢结构厂房里最常见的是 H 型钢柱（H-section column），与梁（beam/girder）组成框架；图纸上柱位决定柱距（column spacing），是方案报价的第一笔大数。", "collocation": "steel column 钢柱；H-section column H 型钢柱；column spacing 柱距；column base 柱脚；side column 边柱；mid column 中柱", "examples": [{"en": "The column spacing is 6 meters along the length of the workshop building.", "zh": "沿厂房纵向柱距为 6 米。", "audio": "audio/ex/column-1.mp3"}], "mnemonic": "column 就是\"顶梁柱\"的那根\"柱\"——楼房塌不塌全看它。联想经典搭配 beam and column（梁柱体系）：beam 横着扛，column 竖着顶。跟已学的 portal frame（第 8 期）连起来记：门式刚架 = 两根 column + 一根 rafter。", "issue": 11, "date": "2026-09-14", "theme": "柱距定结构 → 保温选材料 → 剖面图交底 → 寄样确认 → 谈判收尾", "gloss": "柱；柱子", "category": "钢结构", "audio": "audio/column.mp3"}, {"word": "insulation", "phonetic": "/ˌɪnsjuˈleɪʃn/", "meaning": "阻止热量（或声音、电流）传递的材料或措施；集装箱房、安置房最常见的是夹芯板保温（sandwich panel with insulation），外墙屋面的 insulation 厚度直接决定冬冷夏热地区的居住体验，也是客户验房时最爱问的指标。", "collocation": "thermal insulation 保温隔热；rock wool insulation 岩棉保温；insulation thickness 保温层厚度；sandwich panel insulation 夹芯板保温；sound insulation 隔音", "examples": [{"en": "We upgraded the roof insulation from 50mm to 75mm rock wool for the cold region.", "zh": "针对寒冷地区，我们把屋面保温从 50 毫米升级为 75 毫米岩棉。", "audio": "audio/ex/insulation-1.mp3"}], "mnemonic": "insulate（隔离）+ -ion = 把冷热\"隔离在外\"。三种 insulation 一网打尽：thermal 保温、sound 隔音、electrical 绝缘——都是\"隔\"字诀。跟 cladding（第 10 期）搭配记：cladding 是\"外衣\"，insulation 是外衣里的\"羽绒服\"。", "issue": 11, "date": "2026-09-14", "theme": "柱距定结构 → 保温选材料 → 剖面图交底 → 寄样确认 → 谈判收尾", "gloss": "保温；隔热（材料）", "category": "建筑设计", "audio": "audio/insulation.mp3"}, {"word": "section", "phonetic": "/ˈsekʃn/", "meaning": "把建筑物假想切开一刀、看内部构造的图纸，与平面图（plan）、立面图（elevation）并称三大图；钢结构详图中 section 还指型钢断面（如 H-section H 型钢）；\"Section A-A\" 就是 A-A 剖面。", "collocation": "cross section 横剖面；Section A-A A-A 剖面；section drawing 剖面图；H-section H 型断面；detail section 详图剖面", "examples": [{"en": "Please refer to Section A-A on drawing S-02 for the column base detail.", "zh": "柱脚详图请参见图纸 S-02 的 A-A 剖面。", "audio": "audio/ex/section-1.mp3"}], "mnemonic": "想象拿刀把模型\"咔嚓\"切一刀（cut a section），切面就是 section。制图三兄弟一起记：plan 从上往下看、elevation 从侧面看（第 2 期已学）、section 切开看——\"平面看布局，立面看脸，剖面看里子\"。", "issue": 11, "date": "2026-09-14", "theme": "柱距定结构 → 保温选材料 → 剖面图交底 → 寄样确认 → 谈判收尾", "gloss": "剖面图；断面", "category": "建筑设计", "audio": "audio/section.mp3"}, {"word": "sample", "phonetic": "/ˈsɑːmpl/", "meaning": "外贸中用于确认品质的实物样品；钢结构围护材料常寄彩钢板小样（color coated steel sample）给客户确认颜色和涂层，\"sample approval\"（样品确认）往往是下单（place the order）前的最后一道关；质检语境里还有\"抽样检验\"之意。", "collocation": "free sample 免费样品；sample approval 样品确认；send samples 寄样；color sample 色板；as per sample 按样品；sample inspection 抽样检验", "examples": [{"en": "We will send you color samples of the sandwich panels by DHL for approval before mass production.", "zh": "量产前我们将通过 DHL 寄送夹芯板颜色样品供贵方确认。", "audio": "audio/ex/sample-1.mp3"}], "mnemonic": "sample 谐音\"三婆\"——三婆买菜先\"取样\"尝一口再买整筐。外贸流程一句话记住它：quotation（报价）→ sample（寄样）→ approval（确认）→ order（下单）。\"as per sample\"（照样品办）是合同里高频短语。", "issue": 11, "date": "2026-09-14", "theme": "柱距定结构 → 保温选材料 → 剖面图交底 → 寄样确认 → 谈判收尾", "gloss": "样品；抽样", "category": "外贸", "audio": "audio/sample.mp3"}, {"word": "negotiation", "phonetic": "/nɪˌɡəʊʃiˈeɪʃn/", "meaning": "买卖双方就价格、付款、交期等条款来回磋商达成一致的过程；外贸谈判常分技术谈判（technical negotiation）和商务谈判（commercial negotiation）两场，一单大工程的成败一半在 negotiation table 上。", "collocation": "price negotiation 价格谈判；enter into negotiation 开始磋商；commercial negotiation 商务谈判；negotiation skills 谈判技巧；after long negotiation 经过长期磋商；under negotiation 磋商中", "examples": [{"en": "After three rounds of negotiation, both parties agreed on the payment terms.", "zh": "经过三轮谈判，双方就付款条款达成一致。", "audio": "audio/ex/negotiation-1.mp3"}], "mnemonic": "neg（否）+ oti（闲暇）+ ation——古人\"忙完正事才有空谈\"，negotiation 就是\"正事\"：谈生意。跟已学 counteroffer（第 10 期）配成一对：counteroffer 是谈判中的一个\"招\"，negotiation 是整场\"局\"。一句口诀：quotation 开价，negotiation 讲价，contract 落笔。", "issue": 11, "date": "2026-09-14", "theme": "柱距定结构 → 保温选材料 → 剖面图交底 → 寄样确认 → 谈判收尾", "gloss": "谈判；磋商", "category": "外贸", "audio": "audio/negotiation.mp3"}, {"word": "crane", "phonetic": "/kreɪn/", "meaning": "施工现场用来把钢梁、钢柱、夹芯板吊到位的机械；钢结构安装（erection）的核心设备，常见的有汽车吊（mobile crane / truck crane）、塔吊（tower crane）、履带吊（crawler crane）；方案阶段要先核算\"吊车站位\"和\"起重半径\"，否则现场吊装会出大问题。外贸报价里 crane 还常指\"主机吊装费用\"这一项。", "collocation": "mobile crane 汽车吊；tower crane 塔吊；crawler crane 履带吊；crane capacity 起重能力；crane rental 吊车租赁；lift by crane 用吊车吊装", "examples": [{"en": "A 50-ton mobile crane will be required to erect the main girders on site.", "zh": "现场吊装主梁需要一台 50 吨汽车吊。", "audio": "audio/ex/crane-1.mp3"}], "mnemonic": "crane 同时也是\"鹤\"的意思——长脖子伸出去吊东西，跟吊车的长臂一模一样。工地三兄弟一起记：crane 吊起来 → erection 装起来（第 6 期）→ weld 焊起来（第 7 期）。跟客户聊方案时一句 \"Do you have a crane on site?\"（现场有吊车吗）能立刻判断施工条件。", "issue": 12, "date": "2026-09-15", "theme": "吊车进场吊装 → 厂房通风设计 → 竣工移交业主 → 装箱单随船 → 赶在截止日前交付", "gloss": "起重机；吊车", "category": "钢结构", "audio": "audio/crane.mp3"}, {"word": "ventilation", "phonetic": "/ˌventɪˈleɪʃn/", "meaning": "让室内外空气流通的设计或措施；钢结构厂房、集装箱房、安置房里通风直接影响居住舒适度和结露问题，常见做法是屋脊通风器（ridge ventilator）、百叶窗（louvers）和侧墙进风；通风不好会让夏天室内温度高出好几度，是海外客户投诉的重灾区。", "collocation": "natural ventilation 自然通风；ridge ventilation 屋脊通风；ventilation system 通风系统；cross ventilation 穿堂风；mechanical ventilation 机械通风；poor ventilation 通风不良", "examples": [{"en": "We added ridge ventilators and wall louvers to improve natural ventilation in the workshop.", "zh": "我们增加了屋脊通风器和墙面百叶，以改善厂房的自然通风。", "audio": "audio/ex/ventilation-1.mp3"}], "mnemonic": "词根 vent- = \"风/来\"（如 adventure 冒险 = 去\"来\"未知之地），vent 本身就有\"通风口、排气\"的意思。联想：window 采光、insulation 保温（第 11 期）、ventilation 换气——房子舒服三件套，缺一不可。口诀：\"不透风的房子住不住人\"。", "issue": 12, "date": "2026-09-15", "theme": "吊车进场吊装 → 厂房通风设计 → 竣工移交业主 → 装箱单随船 → 赶在截止日前交付", "gloss": "通风；换气", "category": "建筑设计", "audio": "audio/ventilation.mp3"}, {"word": "handover", "phonetic": "/ˈhændəʊvə(r)/", "meaning": "工程完工后把项目、钥匙、资料正式交给业主的过程；外贸和工程合同里 \"handover\" 常与 \"takeover\"（接收）成对出现，\"handover date\"（移交日期）和 \"handover certificate\"（移交证书）是收尾款的重要节点；职场里也指工作交接（job handover）。", "collocation": "project handover 项目移交；handover certificate 移交证书；handover date 移交日期；take over 接收；job handover 工作交接；hand over to 移交给", "examples": [{"en": "The final payment will be released within 15 days after project handover.", "zh": "项目移交后 15 天内支付尾款。", "audio": "audio/ex/handover-1.mp3"}], "mnemonic": "hand（手）+ over（过去）= 把手里的东西\"递过去\"，就是移交。动词形式要分开写：hand over the documents（递交文件）；名词连写 handover。跟已学的 bill of lading（第 9 期提单）配成链条：发货 → 清关 → 安装 → handover 移交 → 收尾款。", "issue": 12, "date": "2026-09-15", "theme": "吊车进场吊装 → 厂房通风设计 → 竣工移交业主 → 装箱单随船 → 赶在截止日前交付", "gloss": "移交；交付", "category": "工程设计", "audio": "audio/handover.mp3"}, {"word": "packing list", "phonetic": "/ˈpækɪŋ lɪst/", "meaning": "外贸出口必备单证之一，逐一列明每个包装箱的编号、品名、规格、数量、毛重净重和体积；钢结构项目散件多，装箱单是客户清点构件、清关查验和索赔的依据，必须与实物、发票（invoice）、提单（bill of lading）三者完全一致，否则极易卡关。", "collocation": "detailed packing list 详细装箱单；as per packing list 按装箱单；packing list number 箱单号；gross weight / net weight 毛重/净重；case number 箱号；check against the packing list 对照装箱单清点", "examples": [{"en": "Please check the packing list carefully before signing for the container.", "zh": "签收集装箱前请仔细核对装箱单。", "audio": "audio/ex/packing-list-1.mp3"}], "mnemonic": "pack（打包）+ ing + list（清单）= 打包的清单。外贸单证\"铁三角\"一次记全：proforma invoice 形式发票（第 4 期）→ packing list 装箱单 → bill of lading 提单（第 9 期）。口诀：发票说\"多少钱\"，箱单说\"装了啥\"，提单说\"谁的货\"。", "issue": 12, "date": "2026-09-15", "theme": "吊车进场吊装 → 厂房通风设计 → 竣工移交业主 → 装箱单随船 → 赶在截止日前交付", "gloss": "装箱单", "category": "外贸", "audio": "audio/packing-list.mp3"}, {"word": "deadline", "phonetic": "/ˈdedlaɪn/", "meaning": "必须完成某项工作的最晚时间点；外贸里常指报价有效期、信用证开证期、图纸确认期；工程里是节点工期；职场沟通中 \"meet the deadline\"（按时完成）与 \"miss the deadline\"（逾期）是最常用的两个说法。", "collocation": "meet the deadline 按时完成；miss the deadline 逾期；tight deadline 时间紧；deadline pressure 工期压力；extend the deadline 延长截止日期；deadline is approaching 截止日期临近", "examples": [{"en": "We are working overtime to meet the deadline for the drawing approval.", "zh": "我们正在加班加点，以赶上图审的截止日期。", "audio": "audio/ex/deadline-1.mp3"}], "mnemonic": "dead（死）+ line（线）= \"死线\"，踩上去就完蛋——所以必须赶在前面。跟已学的 lead time（第 2 期交货期）、overtime（第 6 期加班）连成一句职场高频话：The deadline is tight, so we need to work overtime to keep the lead time.（期限紧，得加班才能保证交期。）", "issue": 12, "date": "2026-09-15", "theme": "吊车进场吊装 → 厂房通风设计 → 竣工移交业主 → 装箱单随船 → 赶在截止日前交付", "gloss": "截止日期", "category": "职场", "audio": "audio/deadline.mp3"}, {"word": "corrosion", "phonetic": "/kəˈrəʊʒən/", "meaning": "金属表面与环境（水、氧气、盐分、酸碱）发生化学反应而逐渐被破坏的现象，也就是我们说的\"生锈\"；钢结构项目的头号敌人，海边、化工厂、高湿地区尤其严重，所以才需要 galvanize 热浸镀锌（第 2 期）、涂漆涂装、耐候钢等措施；投标报价里\"防腐等级\"直接决定成本。", "collocation": "corrosion protection 防腐；anti-corrosion coating 防腐涂层；corrosion resistant 耐腐蚀的；corrosion rate 腐蚀速率；marine corrosion 海洋腐蚀；prevent corrosion 防止腐蚀", "examples": [{"en": "Hot-dip galvanizing provides excellent corrosion protection for steel structures in coastal areas.", "zh": "热浸镀锌为沿海地区的钢结构提供了优异的防腐保护。", "audio": "audio/ex/corrosion-1.mp3"}], "mnemonic": "词根 cor-（完全）+ rod/ros（咬，同 rodent 啮齿动物 = 爱咬东西的）= 被一点点\"咬掉\"，就是腐蚀。动词 corrode /kəˈrəʊd/，形容词 corrosive（腐蚀性的）。联想链条：不处理就 corrosion → 所以要 galvanize（第 2 期镀锌）→ 再加 coating 涂装 → 海边项目尤其要 anti-corrosion。", "issue": 13, "date": "2026-09-16", "theme": "钢结构防腐处理 → 高强螺栓扭矩验收 → 天窗采光设计 → 客户索赔处理 → 通勤路上背单词", "gloss": "腐蚀；锈蚀", "category": "钢结构", "audio": "audio/corrosion.mp3"}, {"word": "torque", "phonetic": "/tɔːk/", "meaning": "使物体发生转动的力矩，工程上最常指\"螺栓拧紧力矩\"；高强螺栓连接（anchor bolt 第 6 期、fastener 第 5 期）必须按设计值用扭矩扳手（torque wrench）拧到位，拧松了结构不安全，拧过头螺栓会拉断；安装验收时\"扭矩抽检\"是必查项。汽车参数表里 torque 就是\"扭矩\"。", "collocation": "torque wrench 扭矩扳手；torque value 扭矩值；tightening torque 拧紧力矩；high-strength bolt torque 高强螺栓扭矩；torque control 扭矩控制；apply torque 施加扭矩", "examples": [{"en": "All anchor bolts must be tightened to a torque of 450 Nm with a calibrated torque wrench.", "zh": "所有地脚螺栓必须用校准过的扭矩扳手拧紧到 450 牛·米的力矩。", "audio": "audio/ex/torque-1.mp3"}], "mnemonic": "源自拉丁语 torquere = \"扭、拧\"（同根词 torture 拷问 = 拧着逼供，torch 火把 = 拧成的草把）。记住公式感的一句话：torque = force × distance（力 × 力臂）。工地上三件套一起记：bolt 螺栓 → torque 拧紧 → weld 焊接（第 7 期）——钢结构的三种\"连起来\"的方式。", "issue": 13, "date": "2026-09-16", "theme": "钢结构防腐处理 → 高强螺栓扭矩验收 → 天窗采光设计 → 客户索赔处理 → 通勤路上背单词", "gloss": "扭矩；拧紧力矩", "category": "工程设计", "audio": "audio/torque.mp3"}, {"word": "skylight", "phonetic": "/ˈskaɪlaɪt/", "meaning": "开在屋面上的透光构件，用来给室内引入自然光；钢结构厂房、仓库、安置房常在屋面板（cladding 第 10 期围护板）上顺带做采光带（skylight strip / light band），既能省白天照明电费，又能改善车间舒适度；设计时要注意防水节点、遮阳和抗冲击，热带项目还要考虑隔热。", "collocation": "skylight panel 采光板；skylight strip / light band 采光带；roof skylight 屋顶天窗；natural daylighting 自然采光；FRP skylight 玻璃钢采光板；skylight flashing 天窗泛水", "examples": [{"en": "We suggest adding FRP skylight strips to reduce daytime lighting costs in the workshop.", "zh": "我们建议增加玻璃钢采光带，以降低厂房白天的照明费用。", "audio": "audio/ex/skylight-1.mp3"}], "mnemonic": "sky（天空）+ light（光）= 把天空的光引进来，就是天窗。跟已学的 ventilation（第 12 期通风）、insulation（第 11 期保温）组成\"厂房舒适三件套\"：skylight 管亮、ventilation 管透气、insulation 管冷暖。报价时一句话：Skylight strips are optional, about 8 USD per square meter.（采光带是选配项，约 8 美元一平米。）", "issue": 13, "date": "2026-09-16", "theme": "钢结构防腐处理 → 高强螺栓扭矩验收 → 天窗采光设计 → 客户索赔处理 → 通勤路上背单词", "gloss": "天窗；采光带", "category": "建筑设计", "audio": "audio/skylight.mp3"}, {"word": "claim", "phonetic": "/kleɪm/", "meaning": "外贸与工程里指\"因货损、延误、质量不符等向责任方（供应商、保险公司、船公司）提出赔偿要求\"，是处理售后纠纷的核心词；也作动词表示\"声称\"（He claims that...）；日常生活中还有\"认领\"的意思（baggage claim 行李提取处）。索赔通常需要装箱单、提单、照片等证据。", "collocation": "lodge / file a claim 提出索赔；claim for compensation 索赔；insurance claim 保险理赔；claim against the supplier 向供应商索赔；baggage claim 行李提取处；claim responsibility 声称负责", "examples": [{"en": "The client filed a claim for the damaged cladding panels within seven days of delivery.", "zh": "客户在交付后七天内就损坏的墙面板提出了索赔。", "audio": "audio/ex/claim-1.mp3"}], "mnemonic": "源自拉丁语 clamare = \"喊叫\"（同根词 exclaim 惊呼、proclaim 宣布）——古时候\"喊出来\"主张权利，就是 claim。外贸链条串起来：bill of lading 提单（第 9 期）→ packing list 装箱单（第 12 期）→ 货损 → file a claim 索赔 → insurance 理赔。机场见到 Baggage Claim 就是\"行李认领处\"，一个词两个场景一起记。", "issue": 13, "date": "2026-09-16", "theme": "钢结构防腐处理 → 高强螺栓扭矩验收 → 天窗采光设计 → 客户索赔处理 → 通勤路上背单词", "gloss": "索赔；声称", "category": "外贸", "audio": "audio/claim.mp3"}, {"word": "commute", "phonetic": "/kəˈmjuːt/", "meaning": "每天在家和工作地点之间往返的过程；职场自我介绍、聊生活时极高频率的词，\"My commute is about 40 minutes\"（我通勤大约 40 分钟）；也可指\"减刑\"（commute a sentence），但日常几乎只用通勤义。名词也可作 commuter（通勤者），如 commuter rail 通勤铁路。", "collocation": "daily commute 日常通勤；commute to work 通勤上班；commute time 通勤时间；long commute 通勤时间长；commuter 通勤者；commute by subway 乘地铁通勤", "examples": [{"en": "My daily commute is about 40 minutes, so I review new words on the subway.", "zh": "我每天通勤大约 40 分钟，所以在地铁上复习新单词。", "audio": "audio/ex/commute-1.mp3"}], "mnemonic": "前缀 com-（共同）+ mute（改变，如 mutation 变异）= 每天\"来回切换\"地点，就是通勤。谐音记：com-mute ≈ \"啃马路通勤\"。跟已学的 overtime（第 6 期加班）、workload（第 3 期工作量）、deadline（第 12 期截止日期）组成\"打工人四件套\"：long commute + heavy workload + tight deadline + work overtime。", "issue": 13, "date": "2026-09-16", "theme": "钢结构防腐处理 → 高强螺栓扭矩验收 → 天窗采光设计 → 客户索赔处理 → 通勤路上背单词", "gloss": "通勤；上下班往返", "category": "职场", "audio": "audio/commute.mp3"}, {"word": "prefabricate", "phonetic": "/priːˈfæbrɪkeɪt/", "meaning": "在工厂里把构件（墙板、楼板、卫生间模块、整间集装箱房）先做好，再运到现场拼装；这是模块化建筑、标准化安置房的核心工艺，也是海外项目压缩工期、控制质量的杀手锏。跟已学的 fabrication（第 1 期，加工制造）是同一词根，只是加了 pre-（提前）：先在厂里 fabrication，到现场只剩 erection（第 6 期，安装吊装）。形容词 prefabricated / prefab（预制的；活动板房）。", "collocation": "prefabricated module 预制模块；prefabricated house 预制房屋；prefabricated bathroom pod 整体卫浴模块；prefab building 装配式建筑；off-site prefabrication 场外预制；prefabricate in the factory 在工厂预制", "examples": [{"en": "All the wall panels are prefabricated in our factory, so the site erection takes only three weeks.", "zh": "所有墙板都在我们工厂预制完成，因此现场安装只需三周。", "audio": "audio/ex/prefabricate-1.mp3"}], "mnemonic": "pre-（提前）+ fabricate（制作，第 1 期 fabrication 的动词）= 提前在厂里做好。记住这个对比句：Traditional building pours on site; prefabricated building builds in the factory.（传统建筑现场浇筑，装配式建筑工厂制造。）做模块化产品库时一句话就够：We prefabricate 80% of the unit; only foundations and connections are done on site.（单元 80% 在厂内预制，只有基础和节点在现场做。）", "issue": 14, "date": "2026-09-17", "theme": "模块化房屋工厂预制 → 场地排水设计 → 质保条款谈妥 → 客户到访接待 → 任务授权分派", "gloss": "预制；工厂化制造", "category": "钢结构", "audio": "audio/prefabricate.mp3"}, {"word": "drainage", "phonetic": "/ˈdreɪnɪdʒ/", "meaning": "把雨水、污水排走的系统或能力，包括屋面天沟、雨水管、场地明沟、集水井等；建筑设计和总平面里必查项，热带雨季项目（非洲、东南亚）尤其关键——排水没做好，基础（foundation 第 9 期）泡水、地面沉降、室内返潮全来了。方案汇报时甲方常问：\"How is the site drainage solved?\"（场地排水怎么解决？）", "collocation": "drainage system 排水系统；site drainage 场地排水；storm drainage 雨水排放；drainage ditch / trench 排水沟；drainage pipe 排水管；poor drainage 排水不畅；roof drainage 屋面排水", "examples": [{"en": "The site has poor drainage, so we raised the floor level by 300 mm and added perimeter ditches.", "zh": "场地排水不畅，所以我们把室内地坪抬高了 300 毫米，并增设了周边排水沟。", "audio": "audio/ex/drainage-1.mp3"}], "mnemonic": "drain（排干 / 下水道）+ -age（名词后缀）。生活里最熟悉的场景：The sink drains slowly.（水池下水很慢。）→ 建筑上就是 drainage。联想\"三大水系统\"一起记：drainage 排水、ventilation 通风（第 12 期）、insulation 保温（第 11 期）——厂房方案里三件套缺一不可。", "issue": 14, "date": "2026-09-17", "theme": "模块化房屋工厂预制 → 场地排水设计 → 质保条款谈妥 → 客户到访接待 → 任务授权分派", "gloss": "排水；排水系统", "category": "工程设计", "audio": "audio/drainage.mp3"}, {"word": "warranty", "phonetic": "/ˈwɒrənti/", "meaning": "卖方对产品质量与性能的书面承诺，在约定年限内免费维修或更换；外贸合同、钢结构供货合同里的核心条款，通常写 \"12 months after shipment or 18 months after delivery, whichever comes first\"（发货后 12 个月或交付后 18 个月，以先到者为准）。注意区分：guarantee 偏\"保证\"，warranty 偏\"书面保修条款\"；claim（第 13 期索赔）往往就是在 warranty 期内提出的。", "collocation": "warranty period 质保期；one-year warranty 一年质保；under warranty 在保修期内；warranty claim 质保索赔；extend the warranty 延长质保；out of warranty 超出保修期；warranty certificate 质保书", "examples": [{"en": "We offer a 12-month warranty on all steel structures against manufacturing defects.", "zh": "我们对所有钢结构提供 12 个月质保，覆盖制造缺陷。", "audio": "audio/ex/warranty-1.mp3"}], "mnemonic": "来自 warrant（保证 / 授权令），-y 名词后缀——\"白纸黑字保证\"就是质保书。谈判高频句：The warranty does not cover damage caused by improper installation.（质保不涵盖因安装不当造成的损坏。）串起外贸链条：quotation 报价（第 1 期）→ deposit 定金（第 3 期）→ shipment 发货（第 6 期）→ warranty 质保 → claim 索赔（第 13 期）。", "issue": 14, "date": "2026-09-17", "theme": "模块化房屋工厂预制 → 场地排水设计 → 质保条款谈妥 → 客户到访接待 → 任务授权分派", "gloss": "质保；保修期", "category": "外贸", "audio": "audio/warranty.mp3"}, {"word": "reception", "phonetic": "/rɪˈsepʃn/", "meaning": "三层常用义——①公司前台 / 接待处（the reception desk，客户进门第一站）；②接待、迎接的行为（give sb a warm reception 热烈接待）；③欢迎会、招待会（hold a reception 举办招待会）。客户接待场景的基础词，跟 hospitality（第 3 期款待）、courtesy（第 2 期礼遇）、itinerary（第 1 期行程）是同一个\"接机组\"。", "collocation": "reception desk / front desk 前台；reception area 接待区；warm reception 热情接待；hold a reception 举办招待会；receptionist 接待员；arrange reception 安排接待", "examples": [{"en": "Our driver will meet you at the reception desk of the hotel at nine tomorrow morning.", "zh": "我们的司机会在明早九点在酒店前台接您。", "audio": "audio/ex/reception-1.mp3"}], "mnemonic": "receive（收到 / 接待）+ -ption 名词后缀 = \"接住来的人\"。一词三义用场景串：到公司先去 reception desk 登记 → 被 give a warm reception 热情接待 → 晚上参加 welcome reception 欢迎会。客户来访邮件万能句：Please let us know your flight details so we can arrange hotel and reception.（请告知航班信息，以便我们安排住宿与接待。）", "issue": 14, "date": "2026-09-17", "theme": "模块化房屋工厂预制 → 场地排水设计 → 质保条款谈妥 → 客户到访接待 → 任务授权分派", "gloss": "接待；前台；欢迎会", "category": "客户接待", "audio": "audio/reception.mp3"}, {"word": "delegate", "phonetic": "/ˈdelɪɡeɪt/", "meaning": "动词最常用——把任务或权力交给别人去做，\"学会 delegate\" 是职场从中级到高级的分水岭；名词读作 /ˈdelɪɡət/，指\"代表、代表团成员\"（如 conference delegate 会议代表）。工程语境里常和 responsibility、authority 连用：delegate responsibility to the site manager（把责任授权给现场经理）。", "collocation": "delegate tasks 分派任务；delegate responsibility / authority 授权；delegate to sb 委派给某人；delegate a job to a colleague 把活儿交给同事；delegation 代表团；learn to delegate 学会授权", "examples": [{"en": "A good project manager knows how to delegate routine tasks and focus on key decisions.", "zh": "优秀的项目经理懂得把日常事务分派下去，自己专注于关键决策。", "audio": "audio/ex/delegate-1.mp3"}], "mnemonic": "de-（向下）+ legate（派遣 / 使节，同根 legacy 遗产、colleague 同事）= 把事情\"往下派\"。职场对照记：workload 太重（第 3 期）→ 要么 work overtime 加班（第 6 期）→ 要么 delegate 分派出去。谐音梗：de-legate ≈ \"代理给他\"。", "issue": 14, "date": "2026-09-17", "theme": "模块化房屋工厂预制 → 场地排水设计 → 质保条款谈妥 → 客户到访接待 → 任务授权分派", "gloss": "授权；分派任务；代表", "category": "职场", "audio": "audio/delegate.mp3"}, {"word": "shear", "phonetic": "/ʃɪə(r)/", "meaning": "让构件相邻两部分沿截面\"错开滑移\"的力或作用，结构计算里与轴力、弯矩并列的三大内力之一；动词指\"剪、剪断\"。钢结构的 shear wall（剪力墙）、shear stud（栓钉/剪力钉）、shear force（剪力）、shear connection（抗剪连接）全是高频词。跟已学的 deflection（第 4 期挠度）、torque（第 13 期扭矩）一起构成\"结构验算三件套\"。", "collocation": "shear force 剪力；shear wall 剪力墙；shear stud / shear connector 栓钉剪力连接件；shear strength 抗剪强度；shear connection 抗剪连接；shear plate 剪切板/连接板；shear failure 剪切破坏", "examples": [{"en": "The beam has enough bending capacity, but we need to check the shear force near the supports.", "zh": "这根梁抗弯承载力够，但我们要验算支座附近的剪力。", "audio": "audio/ex/shear-1.mp3"}], "mnemonic": "和 sheep（羊）同源记忆——\"剪羊毛 shear a sheep\"，动作就是\"一上一下错开剪断\"。工程上记一句：Bending makes it bend; shear makes it slide.（弯矩让它弯，剪力让它错。）做方案汇报时的高频句：The connection is designed as a shear connection, not a moment connection.（这个节点按抗剪连接设计，不是刚接。）", "issue": 15, "date": "2026-09-18", "theme": "剪力验算过审 → 夹层方案增面积 → 脚手架搭设交底 → 客户询盘报价 → 接待前内部简报", "gloss": "剪力；剪切", "category": "钢结构", "audio": "audio/shear.mp3"}, {"word": "mezzanine", "phonetic": "/ˈmezəniːn/", "meaning": "在大空间（厂房、仓库、展厅）内部加建的一层\"半层\"楼板，通常不占满整个平面、层高较低；钢结构项目里最省钱的扩容手段——不扩大占地、不改动外围护（cladding 第 10 期），就能把使用面积翻出 30%~50%，常做办公、备料、休息区。甲方最爱的说法：We can add a mezzanine for storage.（我们可以加个夹层做仓储。）", "collocation": "mezzanine floor 夹层楼面；mezzanine level 夹层；steel mezzanine 钢结构夹层；add / build a mezzanine 加建夹层；mezzanine office 夹层办公室；mezzanine storage 夹层仓储；mezzanine slab 夹层板", "examples": [{"en": "We added a steel mezzanine above the packing area to create extra office space without extending the footprint.", "zh": "我们在包装区上方加建了钢结构夹层，在不扩大占地面积的前提下多出了一块办公空间。", "audio": "audio/ex/mezzanine-1.mp3"}], "mnemonic": "源自意大利语 mezzano（中间的），mezzo = middle——就是\"夹在中间的那层\"。注意发音重音在最前：MEZ-za-neen。方案卖点一句话：A mezzanine gives you a second floor for half the price.（夹层用一半的钱换来二楼。）跟 staircase（第 7 期楼梯）天然成对——加夹层必配楼梯，报价时别漏。", "issue": 15, "date": "2026-09-18", "theme": "剪力验算过审 → 夹层方案增面积 → 脚手架搭设交底 → 客户询盘报价 → 接待前内部简报", "gloss": "夹层；夹层楼面", "category": "建筑设计", "audio": "audio/mezzanine.mp3"}, {"word": "scaffolding", "phonetic": "/ˈskæfəldɪŋ/", "meaning": "施工、安装、检修时搭设的临时作业平台与支撑体系，安装（erection 第 6 期）、墙面板施工、焊接（weld 第 7 期）、涂装防腐全靠它；海外项目报价里 scaffolding 常单独列项，安措费不便宜。安全交底高频：erect scaffolding 搭脚手架、dismantle / strike scaffolding 拆脚手架。", "collocation": "scaffolding system 脚手架体系；erect / put up scaffolding 搭设脚手架；dismantle / strike scaffolding 拆除脚手架；scaffolding tube 脚手架钢管；suspended scaffolding 吊篮/悬挂脚手架；scaffold 脚手架（单数）；working at height 高处作业", "examples": [{"en": "The scaffolding will be erected next Monday so that the cladding work can start on time.", "zh": "脚手架将于下周一搭设完成，这样墙面板施工就能按时开始。", "audio": "audio/ex/scaffolding-1.mp3"}], "mnemonic": "scaffold 原指\"台子、断头台\"，-ing 变成体系——给工人搭的\"临时台子\"。词根联想：platform（平台）是永久的，scaffolding 是临时的。工地三件事常连着说：crane 吊车（第 12 期）起吊 → scaffolding 脚手架上人作业 → handover 移交（第 12 期）前全部拆完。客户问工期时可以答：Cladding starts once the scaffolding is up.（脚手架一搭好，墙面板就进场。）", "issue": 15, "date": "2026-09-18", "theme": "剪力验算过审 → 夹层方案增面积 → 脚手架搭设交底 → 客户询盘报价 → 接待前内部简报", "gloss": "脚手架", "category": "工程施工", "audio": "audio/scaffolding.mp3"}, {"word": "inquiry", "phonetic": "/ɪnˈkwaɪəri/", "meaning": "外贸流程的第一棒——客户发来的询问/询价函，英式也拼 enquiry（发音一样）。\"收到询盘\"就是 receive an inquiry，\"回复询盘\"是 reply to an inquiry / follow up on an inquiry（follow-up 第 5 期）。完整链条：inquiry 询盘 → quotation 报价（第 1 期）→ counteroffer 还盘（第 10 期）→ deposit 定金（第 3 期）→ shipment 发货（第 6 期）。", "collocation": "inquiry letter 询价函；receive / get an inquiry 收到询盘；reply to an inquiry 回复询盘；inquiry about prices 询价；make an inquiry 询问；inquiry form 询价表；thank you for your inquiry 感谢您的询价", "examples": [{"en": "We received an inquiry from a Kenyan client for 200 prefabricated housing units yesterday.", "zh": "昨天我们收到一位肯尼亚客户关于 200 套预制房屋的询盘。", "audio": "audio/ex/inquiry-1.mp3"}], "mnemonic": "inquire（询问 v.）+ -y 名词后缀；谐音\"因快而\"——客户\"因想快\"才来询价。邮件开场白万能句：Thank you for your inquiry dated 18 September regarding our steel warehouse.（感谢您 9 月 18 日关于我司钢结构仓库的询盘。）区分：inquiry 是客户问价，quotation 是我们报价，counteroffer 是客户还价。", "issue": 15, "date": "2026-09-18", "theme": "剪力验算过审 → 夹层方案增面积 → 脚手架搭设交底 → 客户询盘报价 → 接待前内部简报", "gloss": "询价；询盘", "category": "外贸", "audio": "audio/inquiry.mp3"}, {"word": "briefing", "phonetic": "/ˈbriːfɪŋ/", "meaning": "把关键信息在短时间内讲清楚的小型会议/文件，是客户接待与项目管理的衔接点——客户到访先开个 briefing（项目简报会），工人进场先做 safety briefing（安全交底），设计师出图前听 design briefing（设计任务简报）。动词 brief sb on sth = 就某事向某人做简要说明。", "collocation": "safety briefing 安全交底；project briefing 项目简报；design brief / briefing 设计任务书交底；brief sb on sth 就某事向某人简要说明；hold / give a briefing 举行简报会；press briefing 新闻发布会；debrief 事后复盘", "examples": [{"en": "Before the site visit, I'll give you a ten-minute briefing on the project scope and schedule.", "zh": "在现场考察之前，我会就项目范围和进度给您做一个十分钟的简报。", "audio": "audio/ex/briefing-1.mp3"}], "mnemonic": "brief（简短的）+ -ing = \"简短地说一遍\"。一词串全场：客户落地 → reception 接待（第 14 期）→ briefing 简报会 → site visit 现场考察（第 8 期）→ agenda 议程（第 4 期）逐条过。职场金句：Keep it brief.（长话短说。）—— 说完就开 briefing。", "issue": 15, "date": "2026-09-18", "theme": "剪力验算过审 → 夹层方案增面积 → 脚手架搭设交底 → 客户询盘报价 → 接待前内部简报", "gloss": "简报；交底会", "category": "客户接待", "audio": "audio/briefing.mp3"}, {"word": "grout", "phonetic": "/ɡraʊt/", "meaning": "一种流动性好的水泥基砂浆，用来填满柱脚底板与基础（foundation 第 9 期）之间、或地脚螺栓（anchor bolt 第 6 期）孔里的空隙，使荷载均匀传递并防止螺栓锈蚀。钢结构安装里叫二次灌浆（secondary grouting），是 erection 之后、正式受荷之前的关键工序。动词 grout = 灌浆：grout the base plate / grout the anchor bolts。", "collocation": "cementitious grout 水泥基灌浆料；non-shrink grout 无收缩灌浆料；grout the base plate 柱脚底板灌浆；secondary grouting 二次灌浆；grout hole 灌浆孔；grout thickness 灌浆层厚度；epoxy grout 环氧灌浆料", "examples": [{"en": "After the columns are aligned, we will grout the base plates with non-shrink grout.", "zh": "钢柱校正之后，我们会用无收缩灌浆料给柱脚底板灌浆。", "audio": "audio/ex/grout-1.mp3"}], "mnemonic": "和 grout 长得像的 group（组）、grout（灌浆）——记\"给柱脚'糊'一层\"：grout 读 /ɡraʊt/，与 out 押韵，想象\"把空隙 pour out（灌出去）\"。工地高频句：Make sure the grout is fully compacted under the base plate.（务必保证底板下方灌浆密实。）搭配已学的 anchor bolt + foundation + torque（终拧扭矩）一起记，就是柱脚施工完整三步。", "issue": 16, "date": "2026-09-19", "theme": "柱脚二次灌浆 → 入口雨棚造型 → 谈最小起订量 MOQ → 客户接待礼宾规程 → 差旅报销", "gloss": "灌浆；灌浆料", "category": "工程施工", "audio": "audio/grout.mp3"}, {"word": "canopy", "phonetic": "/ˈkænəpi/", "meaning": "从建筑外墙挑出、悬在入口或装卸区上方的轻型遮挡结构，钢结构项目里几乎必配——入口雨棚、加油站罩棚、卸货区防雨棚都叫 canopy。常做成钢结构骨架 + 夹芯板或张拉膜，与 facade（第 5 期立面）、cladding（第 10 期围护板）同一族。它本质上就是\"小小的 cantilever（第 3 期悬臂）\"。", "collocation": "entrance canopy 入口雨棚；canopy roof 棚顶；steel canopy 钢结构雨棚；loading canopy 卸货雨棚；fuel station canopy 加油站罩棚；canopy light 棚下灯具；under the canopy 在棚下", "examples": [{"en": "The entrance canopy will be extended by two meters to keep the loading area dry in the rainy season.", "zh": "入口雨棚会外挑延长两米，让装卸区在雨季也能保持干燥。", "audio": "audio/ex/canopy-1.mp3"}], "mnemonic": "源自希腊语 kōnōpeion（蚊帐），本义是\"罩在上方的一层\"。谐音\"坎诺批\"——门口\"坎\"上头\"批\"一层顶。记忆画面：canopy 就是建筑的\"帽檐\"。方案汇报常用：We suggest a steel canopy over the main entrance for both shading and rain protection.（我们建议在主入口上方做钢结构雨棚，兼顾遮阳与防雨。）", "issue": 16, "date": "2026-09-19", "theme": "柱脚二次灌浆 → 入口雨棚造型 → 谈最小起订量 MOQ → 客户接待礼宾规程 → 差旅报销", "gloss": "雨棚；挑棚", "category": "建筑设计", "audio": "audio/canopy.mp3"}, {"word": "MOQ", "phonetic": "/ˌem əʊ ˈkjuː/", "meaning": "外贸报价里最常被客户追问的一条——供应商愿意接单的最小数量/最小金额。低于 MOQ 要么不接，要么加收小额附加费（small order surcharge）。完整谈判链条：inquiry 询盘（第 15 期）→ quotation 报价（第 1 期）→ MOQ 起订量 → lead time 交货期（第 2 期）→ counteroffer 还盘（第 10 期）→ deposit 定金（第 3 期）。", "collocation": "MOQ / minimum order quantity 最小起订量；What is your MOQ? 你们起订量是多少；MOQ of 100 units 100 台起订；lower the MOQ 降低起订量；meet the MOQ 达到起订量；MOQ requirement 起订量要求；small order surcharge 小单附加费", "examples": [{"en": "Our MOQ is one 40-foot container, but we can mix different models in the same container.", "zh": "我们的最小起订量是一个 40 英尺集装箱，但同一个柜里可以混装不同型号。", "audio": "audio/ex/moq-1.mp3"}], "mnemonic": "直接念三个字母 M-O-Q，别硬读成单词。记一句话：M = Minimum（最小），O = Order（订单），Q = Quantity（数量）。客户砍价时最实用的一句：If you can meet the MOQ, we can offer a better unit price.（如果能达到起订量，我们可以给更好的单价。）—— 用 MOQ 换价格，是外贸最经典的交换条件。", "issue": 16, "date": "2026-09-19", "theme": "柱脚二次灌浆 → 入口雨棚造型 → 谈最小起订量 MOQ → 客户接待礼宾规程 → 差旅报销", "gloss": "最小起订量", "category": "外贸", "audio": "audio/moq.mp3"}, {"word": "protocol", "phonetic": "/ˈprəʊtəkɒl/", "meaning": "正式场合（迎送客户、签约仪式、政府会见）约定俗成的行为规矩与流程安排，也指正式的\"议定书/协议\"。接待海外客户时讲的 protocol 包括：谁去接机（pick-up 第 4 期）、座位怎么排、谁先致辞、名片怎么递、礼品怎么送。用错 protocol 比说错英语更尴尬。", "collocation": "diplomatic protocol 外交礼宾；follow the protocol 遵循礼宾规程；protocol officer 礼宾官；signing protocol 签约议定书；protocol for receiving guests 接待宾客的礼仪规范；breach of protocol 失礼；seat arrangement protocol 座次安排", "examples": [{"en": "According to protocol, our general manager will meet the delegates at the entrance and exchange business cards first.", "zh": "按照礼宾规程，我们总经理会在入口迎接代表团，并先行交换名片。", "audio": "audio/ex/protocol-1.mp3"}], "mnemonic": "proto-（第一、原始）+ -col（胶水）= 古卷宗的\"第一页扉页\"，引申为\"规矩、规程\"。谐音\"普若套扣\"——接待客户要\"按套路来\"。行业金句：When in doubt, follow the protocol.（拿不准的时候，就按规矩办。）接待三件套：protocol 规矩 → reception 接待（第 14 期）→ hospitality 款待（第 3 期）。中东、非洲客户尤其看重座次与迎接规格，提前跟中方对接人确认 protocol 能省掉很多麻烦。", "issue": 16, "date": "2026-09-19", "theme": "柱脚二次灌浆 → 入口雨棚造型 → 谈最小起订量 MOQ → 客户接待礼宾规程 → 差旅报销", "gloss": "礼宾规程；礼仪", "category": "客户接待", "audio": "audio/protocol.mp3"}, {"word": "reimbursement", "phonetic": "/ˌriːɪmˈbɜːsmənt/", "meaning": "先自己垫付、事后拿票据向公司或对方收回款项的行为与流程，是出差、客户接待、样品寄送后绕不开的一环。动词 reimburse（报销给某人）：reimburse sb for sth。相关高频词还有 expense claim / expense report（费用报销单）——expense report 每月都要填，堪称打工人月度必修课。", "collocation": "expense reimbursement 费用报销；travel reimbursement 差旅报销；reimbursement request 报销申请；reimburse sb for sth 就某事向某人报销；submit a reimbursement 提交报销；reimbursement policy 报销制度；out-of-pocket expenses 垫付费用；receipt 收据/发票", "examples": [{"en": "Please keep all the receipts so that I can submit the travel reimbursement by Friday.", "zh": "请把所有票据留好，这样我周五前就能提交差旅报销。", "audio": "audio/ex/reimbursement-1.mp3"}], "mnemonic": "re-（回）+ im-（进入）+ burse（钱包，同 purse）+ -ment = \"钱回到钱包里\"。拆解：re + im + purse + ment → 把钱再放回你的 purse。职场三连：垫钱 pay out of pocket → 留票据 keep the receipt → 走报销 file a reimbursement。国外客户来华、或我们出差验厂，机票酒店常走这个流程，报销单英文就叫 expense report。", "issue": 16, "date": "2026-09-19", "theme": "柱脚二次灌浆 → 入口雨棚造型 → 谈最小起订量 MOQ → 客户接待礼宾规程 → 差旅报销", "gloss": "报销；偿付", "category": "职场", "audio": "audio/reimbursement.mp3"}, {"word": "splice", "phonetic": "/splaɪs/", "meaning": "把两根钢构件（梁、柱、钢筋）在长度方向接成一根的连接做法。跨度太大、构件太长没法整根运输时，就分段发运、到现场 splice（拼接）。常见形式：bolted splice 螺栓拼接（用 splice plate 拼接板 + 高强螺栓）、welded splice 焊接拼接。注意区分：splice 是\"同方向接长\"，而 connection/joint 是\"节点相交连接\"（如 gusset 第 4 期节点板）。", "collocation": "splice plate 拼接板；bolted splice 螺栓拼接；welded splice 焊接拼接；field splice 现场拼接；splice joint 拼接接头；beam splice 钢梁拼接；splice the girder 拼接主梁；splice location 拼接位置", "examples": [{"en": "The girder is too long to ship in one piece, so we will use a bolted splice with splice plates at mid-span.", "zh": "这根主梁太长没法整根发运，所以我们在跨中采用拼接板的螺栓拼接。", "audio": "audio/ex/splice-1.mp3"}], "mnemonic": "和 slice（切片）同源的\"接起来\"意象——splice 读作 /splaɪs/，与 nice、price 押韵。记画面：把两截钢梁用板子\"夹三明治\"。运输决定拼接：海运集装箱限长，所以海外项目 90% 的长梁都要 splice。高频句：Where is the splice location?（拼接点设在哪里？）——设跨中 1/3 处（弯矩小）是常识，答出来显得专业。", "issue": 17, "date": "2026-09-20", "theme": "钢梁现场拼接 → 墙身百叶通风 → 竣工调试投运 → 提单收货人确认 → 会面守时接待", "gloss": "拼接；拼接板", "category": "钢结构", "audio": "audio/splice.mp3"}, {"word": "louver", "phonetic": "/ˈluːvə/", "meaning": "由一排倾斜叶片组成的开口，既能通风又能挡雨、遮阳、防窥视。钢结构厂房山墙、设备房外墙、发电机房、空调机房几乎必用；也指天花送风口（air louver）。和已学的 ventilation（第 12 期通风）、cladding（第 10 期围护板）、insulation（第 11 期保温）是同一套围护系统语言。", "collocation": "louver / louvre 百叶；fixed louver 固定百叶；adjustable louver 可调百叶；louver panel 百叶板；louver door 百叶门；exhaust louver 排风百叶；rain-proof louver 防雨百叶；louver blade 百叶叶片；louvered screen 百叶格栅", "examples": [{"en": "We will add rain-proof louvers on both gable walls to improve natural ventilation in the workshop.", "zh": "我们会在两侧山墙加装防雨百叶，以改善厂房的自然通风。", "audio": "audio/ex/louver-1.mp3"}], "mnemonic": "谐音\"卢屋\"——卢浮宫（Louvre）那座玻璃金字塔旁边的老建筑，\"一片一片斜着排\"。记关键：叶片斜着向下外倾 = 通风不淋雨。方案沟通常问：Do you need fixed or adjustable louvers?（要固定百叶还是可调百叶？）中东、非洲项目高温，百叶 + 屋脊通风器（ridge ventilator）是最经济的降温组合。", "issue": 17, "date": "2026-09-20", "theme": "钢梁现场拼接 → 墙身百叶通风 → 竣工调试投运 → 提单收货人确认 → 会面守时接待", "gloss": "百叶；通风百叶", "category": "建筑设计", "audio": "audio/louver.mp3"}, {"word": "commissioning", "phonetic": "/kəˈmɪʃənɪŋ/", "meaning": "机电、设备、系统安装完成后，通电通水、逐项测试直到能正式交付使用的全过程。钢结构厂房里指行车、通风、消防、照明、门系统等全部试车。它和 handover（第 12 期移交）是前后脚：commissioning 完成并出具报告 → 才签字 handover。动词 commission（调试/投运），人作主语时也有\"任命、委托\"之意（commission an artist 委托艺术家创作）。", "collocation": "commissioning 调试/试运行；pre-commissioning 调试前准备；commissioning plan 调试计划；commissioning report 调试报告；commissioning test 调试试验；site commissioning 现场调试；commission the system 系统投运；testing and commissioning 测试与调试；commissioning engineer 调试工程师", "examples": [{"en": "All the cranes and ventilation systems must pass commissioning before we hand over the workshop to the client.", "zh": "所有行车和通风系统必须通过调试，我们才能把厂房移交给客户。", "audio": "audio/ex/commissioning-1.mp3"}], "mnemonic": "commission 本义\"委任、授权\"→ 把设备\"授权上岗\"。拆：com-（共同）+ mission（任务）= 一起完成任务。记链条：install 安装（erection 第 6 期）→ test 测试 → commission 调试投运 → handover 移交。合同里常见 T&C（Testing and Commissioning）缩写，付款节点往往卡在 commissioning certificate 出具时。", "issue": 17, "date": "2026-09-20", "theme": "钢梁现场拼接 → 墙身百叶通风 → 竣工调试投运 → 提单收货人确认 → 会面守时接待", "gloss": "调试；投产试运行", "category": "工程", "audio": "audio/commissioning.mp3"}, {"word": "consignee", "phonetic": "/ˌkɒnsaɪˈniː/", "meaning": "海运提单、发票、装箱单上写明的目的港收货方，通常是买方（或其指定代理）。和 shipper / consignor（发货人）是一对。外贸单据里的坑：consignee 写错一个字母，目的港就提不了货，改单费（amendment fee）常由出错方承担。相关单据词已学：bill of lading 提单（第 9 期）、packing list 装箱单（第 12 期）、customs clearance 清关（第 7 期）。", "collocation": "consignee 收货人；consignee name / address 收货人名称/地址；notify party 通知人；shipper / consignor 发货人；to order of consignee 凭收货人指示；consignee box 收货人栏；consignment 一批托售/发出的货物；consignee information 收货人信息", "examples": [{"en": "Please double-check the consignee name on the bill of lading, because a spelling mistake will delay customs clearance.", "zh": "请务必核对提单上的收货人名称，因为拼写错误会导致清关延误。", "audio": "audio/ex/consignee-1.mp3"}], "mnemonic": "-ee 在英语里表示\"被……的人\"（employee 被雇用的人、trainee 受训者），所以 consignee = 被托运给的人 = 收货人；consignor / shipper = 发货的人。三组对比一次记：employee 雇员 / employer 雇主；trainee 学员 / trainer 教练；consignee 收货人 / consignor 发货人。寄单前必发的一句：Please confirm the consignee details before we issue the bill of lading.（出提单前请确认收货人资料。）", "issue": 17, "date": "2026-09-20", "theme": "钢梁现场拼接 → 墙身百叶通风 → 竣工调试投运 → 提单收货人确认 → 会面守时接待", "gloss": "收货人", "category": "外贸", "audio": "audio/consignee.mp3"}, {"word": "punctual", "phonetic": "/ˈpʌŋktʃuəl/", "meaning": "按约定时间到达或完成，不早不晚。客户接待与职场里最基础也最被看重的品质——接机（pick-up 第 4 期）、会议、验厂（site visit 第 8 期）、宴请（banquet 第 9 期）全都靠它。名词 punctuality（守时）。反义：late / delayed；近义：on time（口语更常用）、on schedule（按计划）。", "collocation": "be punctual 守时；punctual arrival 准时到达；punctuality 守时（名词）；as punctual as clockwork 像钟表一样准；punctual payment 按期付款；punctual delivery 按期交付；Please be punctual. 请准时", "examples": [{"en": "Our driver will be at the airport two hours early, so please don't worry about being punctual for the flight.", "zh": "我们的司机会提前两小时到机场，所以不用担心赶不上飞机。", "audio": "audio/ex/punctual-1.mp3"}], "mnemonic": "词根 punct- = 点（point / puncture 刺穿 / punctuation 标点符号），punctual = 正踩在那个\"点\"上。记一句对比：on time 是\"按时到了\"，in time 是\"及时赶上（差一点就晚）\"，别混。接待客户时最好用的一句自证：We are always punctual for site visits and meetings.（我们考察和会面一向守时。）——德国、日本客户对此极度敏感，非洲、南美客户相对宽松，但都不能迟到大半天。", "issue": 17, "date": "2026-09-20", "theme": "钢梁现场拼接 → 墙身百叶通风 → 竣工调试投运 → 提单收货人确认 → 会面守时接待", "gloss": "准时的；守时的", "category": "职场", "audio": "audio/punctual.mp3"}, {"word": "camber", "phonetic": "/ˈkæmbər/", "meaning": "钢梁在工厂加工时刻意做向上的微微弯曲，用来抵消受荷后向下的 deflection（第 4 期挠度）。30 米跨度的主梁满载时可能下挠 60–80 mm，如果预先 camber 50 mm，视觉上就基本是平的，客户也不会觉得\"梁弯了\"。常见说法：natural camber（轧制自然拱）、pre-camber / pre-cambered beam（预起拱梁）。注意别和 camber 在道路工程里的\"路拱\"混淆，也别拼成 camBER 重音错位——重音在第一个音节。", "collocation": "camber 起拱/预拱度；pre-cambered beam 预起拱梁；camber the girder 给主梁起拱；camber value 起拱值；natural mill camber 轧制自然拱；camber diagram 起拱图；zero camber 不起拱；camber tolerance 起拱允许偏差", "examples": [{"en": "We will pre-camber the 30-metre girder by 50 mm so that the deflection under full load will be almost invisible.", "zh": "我们会给这根 30 米主梁预起拱 50 毫米，这样满载时的下挠几乎看不出来。", "audio": "audio/ex/camber-1.mp3"}], "mnemonic": "camber 和 camera 前半截一样，想象\"给钢梁拍证件照时，摄影师说：抬头挺胸——微微上扬一点\"。技术要点一句话：camber 抵消 deflection。客户问 Why is the beam curved?（梁怎么是弯的？）你就答 It's pre-cambered.（这是预起拱。）——这句话一出口，对方就知道你懂行，是海外项目现场最高频的\"专业感时刻\"之一。", "issue": 18, "date": "2026-09-21", "theme": "大跨钢梁预设起拱 → 建筑动线与中庭方案 → 合同不可抗力条款 → 客户关系建立默契 → 告别拖延按期交付", "gloss": "起拱；预拱度", "category": "钢结构", "audio": "audio/camber.mp3"}, {"word": "circulation", "phonetic": "/ˌsɜːrkjəˈleɪʃən/", "meaning": "人在建筑内部走动、车在场区内通行的组织路径，是方案设计的核心语言之一。分为 pedestrian circulation（人行流线）、vehicle circulation（车行流线）、vertical circulation（竖向交通——楼梯 staircase 第 7 期、电梯、坡道）。图纸说明和方案汇报里几乎必出现，和已学的 layout（第 6 期平面布置）、elevation（第 2 期立面）、section（第 11 期剖面）、rendering（第 8 期效果图）是一套汇报词汇。它还有\"血液循环\"\"货币流通\"\"报纸发行量\"等生活义，词根 circ- = 圈（circle 圆、circuit 回路）。", "collocation": "circulation 流线/动线；circulation route 流线路径；pedestrian circulation 人行流线；vehicle circulation 车行流线；vertical circulation 竖向交通；circulation space 交通空间；circulation core 交通核；circulation diagram 流线分析图；good / poor circulation 流线顺畅/不畅", "examples": [{"en": "The circulation diagram shows that workers can reach the packing area without crossing the truck route.", "zh": "流线分析图显示，工人可以不穿越货车路线就到达包装区。", "audio": "audio/ex/circulation-1.mp3"}], "mnemonic": "circ-（圆、环）+ -ation = 绕着走一圈 → 人和车\"怎么绕\"就是流线。做方案汇报时这句万能开场：This diagram explains the circulation.（这张图讲流线。）顺手记住黄金搭配：layout 讲\"摆在哪\"，circulation 讲\"怎么走\"，两个词一起说，方案逻辑立刻立体。厂房方案里客户最在意的往往是\"人车分流\"——separate pedestrian and vehicle circulation。", "issue": 18, "date": "2026-09-21", "theme": "大跨钢梁预设起拱 → 建筑动线与中庭方案 → 合同不可抗力条款 → 客户关系建立默契 → 告别拖延按期交付", "gloss": "流线；动线；流通", "category": "建筑设计", "audio": "audio/circulation.mp3"}, {"word": "force majeure", "phonetic": "/ˌfɔːrs mɑːˈʒɜːr/", "meaning": "合同法里的免责条款，指不能预见、不能避免、不能克服的客观情况——地震、洪水、战争、罢工、疫情、港口封锁等。外贸合同几乎必备 FM clause（不可抗力条款）。关键实务点：不可抗力 ≠ 随便延期。通常要求受影响方在 15 天内书面通知，并提供官方证明（如贸促会出具的 force majeure certificate），否则照样要赔 delay damages（延期违约金，对应 deadline 第 12 期）。", "collocation": "force majeure 不可抗力；force majeure clause 不可抗力条款；force majeure event 不可抗力事件；force majeure certificate 不可抗力证明；invoke force majeure 援引不可抗力；act of God 天灾（近义，英美法常用）；beyond our reasonable control 超出合理控制范围", "examples": [{"en": "The contract allows us to extend the delivery time by 30 days in case of a force majeure event such as a port strike.", "zh": "合同允许我们在发生港口罢工等不可抗力事件时，把交货期延长 30 天。", "audio": "audio/ex/force-majeure-1.mp3"}], "mnemonic": "这是个法语借词，force = 力量，majeure = 更大的（major），合起来\"更大的力量\"→ 人力不可抗。三个\"不\"是判断标准： unforeseeable（不可预见）+ unavoidable（不能避免）+ insurmountable（不能克服）。实战金句：We will issue the force majeure certificate within 15 days.（我们会在 15 天内出具不可抗力证明。）——遇到物流瘫痪、红海绕航、台风封港，这句话能救一单。", "issue": 18, "date": "2026-09-21", "theme": "大跨钢梁预设起拱 → 建筑动线与中庭方案 → 合同不可抗力条款 → 客户关系建立默契 → 告别拖延按期交付", "gloss": "不可抗力", "category": "外贸", "audio": "audio/force-majeure.mp3"}, {"word": "rapport", "phonetic": "/ræˈpɔːr/", "meaning": "人与人之间那种\"聊得来、互相信任\"的良好关系，比 relationship 更强调\"快速建立起来的亲近感\"。客户接待、商务谈判（negotiation 第 11 期）、跨部门沟通里都极其常用。动词搭配是 build / establish / develop rapport with someone。注意发音：/ræˈpɔːr/，重音在第二音节，结尾的 t 不发音（法语痕迹），别读成\"report\"。", "collocation": "build rapport 建立默契；establish rapport with a client 与客户建立融洽关系；good rapport 关系融洽；rapport building 破冰/关系建立；personal rapport 私人交情；have a good rapport with the team 和团队很投契", "examples": [{"en": "We spent the first ten minutes of the meeting building rapport before we started talking about the quotation.", "zh": "会议开始前十分钟我们先聊了些轻松话题建立默契，之后才谈报价。", "audio": "audio/ex/rapport-1.mp3"}], "mnemonic": "又一个法语词，ra-（回）+ port（带）= \"把对方带回到你这边\"。谐音记：\"rap-port\"——像说唱（rap）一样你来我往、对得上拍子，就是 rapport。跨文化实战：中东、南美客户必须先聊家常再谈生意，跳过 rapport 直接报价往往谈崩；德国、日本客户则可以少寒暄、多数据，但同样认可\"靠谱的默契\"。万能句：Let's build some rapport first.（我们先熟络一下。）", "issue": 18, "date": "2026-09-21", "theme": "大跨钢梁预设起拱 → 建筑动线与中庭方案 → 合同不可抗力条款 → 客户关系建立默契 → 告别拖延按期交付", "gloss": "默契；融洽关系", "category": "客户接待", "audio": "audio/rapport.mp3"}, {"word": "procrastinate", "phonetic": "/prəˈkræstɪneɪt/", "meaning": "明知该做却一再往后推，是职场与自我管理里的高频词。名词 procrastination（拖延症），人叫 procrastinator。它和 delay（客观延迟）、postpone（主动改期）不同：procrastinate 特指\"自己拖自己\"，带轻微贬义。对应已学的 deadline（第 12 期截止日期）、workload（第 3 期工作量）、overtime（第 6 期加班）——拖延的直接后果就是加班。", "collocation": "procrastinate 拖延；stop procrastinating 别再拖了；procrastinate on a task 在任务上拖延；procrastination 拖延（名词）；chronic procrastinator 长期拖延的人；procrastinate until the deadline 拖到截止日", "examples": [{"en": "Don't procrastinate on the shop drawings, or we will have to work overtime again this weekend.", "zh": "别在加工图上拖延了，不然这个周末我们又得加班。", "audio": "audio/ex/procrastinate-1.mp3"}], "mnemonic": "词根拆解超好记：pro-（向前）+ cras（拉丁语\"明天\"）+ -tinate → \"推到明天再说\" = 拖延。西班牙语里\"明天\"正是 mañana，同一个拖延意象。破解法（两分钟法则）：If it takes less than two minutes, do it now.（两分钟能搞定的，现在就做。）每天背这 5 个词本身就是在对抗 procrastinate——今天你已经赢了。", "issue": 18, "date": "2026-09-21", "theme": "大跨钢梁预设起拱 → 建筑动线与中庭方案 → 合同不可抗力条款 → 客户关系建立默契 → 告别拖延按期交付", "gloss": "拖延；耽搁", "category": "职场生活", "audio": "audio/procrastinate.mp3"}, {"word": "shim", "phonetic": "/ʃɪm/", "meaning": "钢柱安装时塞在柱底板（base plate）与混凝土基础（foundation 第 9 期）之间的薄钢片，用来调整标高和垂直度——因为基础顶面不可能浇得绝对平整，全靠 shim 找平。标准是成组使用（shim pack 垫铁组），调平合格后做二次灌浆（grout 第 16 期），把垫铁永久封在里面。也可作动词：shim it up（把它垫起来）。它和 washer（垫圈）、gasket（密封垫片）不是一个东西，别混用。", "collocation": "shim 垫片/垫铁；shim plate 垫板；shim pack 垫铁组；steel shim 钢垫片；leveling shim 调平垫铁；shim up the column 把柱子垫起来；packing shim 填隙片；shim thickness 垫片厚度；stainless shim 不锈钢垫片", "examples": [{"en": "The erection crew used a 6 mm shim pack to level the column base plate before final grouting.", "zh": "安装班组在最终灌浆前，用 6 毫米的垫铁组把柱底板调平。", "audio": "audio/ex/shim-1.mp3"}], "mnemonic": "shim 只有三个字母，却\"短小精悍\"——像它的实物一样，薄薄一片却能扛起整根柱子。画面记忆：柱子站不稳 → 塞一片 → 再塞一片 → 水平尺气泡居中 → 灌浆封死。现场口语：Add one more shim.（再加一片垫铁。）这个词在 erection（第 6 期安装）、column（第 11 期柱）、grout（第 16 期灌浆）的现场对话里几乎天天出现，三个词串起来就是完整的\"钢柱安装四步曲\"。", "issue": 19, "date": "2026-09-22", "theme": "柱底垫铁调平找正 → 室内隔断与空间划分 → 客户 T/T 汇款到账 → 指定项目联络人对接 → 赶图旺季警惕职业倦怠", "gloss": "垫片；垫铁", "category": "工程施工", "audio": "audio/shim.mp3"}, {"word": "partition", "phonetic": "/pɑːrˈtɪʃn/", "meaning": "把一个大空间分成若干小空间的非承重墙体，是建筑设计和室内改造的核心词。轻钢龙骨石膏板隔断叫 drywall partition / stud partition，可移动的叫 movable / demountable partition，玻璃的叫 glass partition。它和已学的 layout（第 6 期平面布置）、mezzanine（第 14 期夹层）、insulation（第 11 期保温）是一套空间词汇。动词用法：partition off a corner（隔出一个角落）；也常见于计算机\"磁盘分区\"，一词多义很好用。", "collocation": "partition 隔断/隔墙；glass partition 玻璃隔断；movable partition 活动隔断；partition wall 隔墙；stud partition 轻钢龙骨隔墙；fire-rated partition 防火隔墙；partition layout 隔断布置；partition off 隔开；toilet partition 卫生间隔断", "examples": [{"en": "We can use demountable glass partitions so the client can change the office layout without any structural work.", "zh": "我们可以采用可拆装的玻璃隔断，这样客户不用做结构改动就能调整办公室布局。", "audio": "audio/ex/partition-1.mp3"}], "mnemonic": "part（部分）+ -ition（名词后缀）= \"分成几部分\"的东西 → 隔断。集装箱房和模块化房屋报价里，客户最爱问的加价项之一就是 interior partition（内隔墙）——记住这句话：Partitions are non-load-bearing.（隔断是非承重的。）一秒区分 partition 和 shear wall（剪力墙），专业度立刻拉满。", "issue": 19, "date": "2026-09-22", "theme": "柱底垫铁调平找正 → 室内隔断与空间划分 → 客户 T/T 汇款到账 → 指定项目联络人对接 → 赶图旺季警惕职业倦怠", "gloss": "隔断；隔墙", "category": "建筑设计", "audio": "audio/partition.mp3"}, {"word": "remittance", "phonetic": "/rɪˈmɪtns/", "meaning": "外贸付款方式 T/T（Telegraphic Transfer 电汇）里的正式说法，指买方把货款汇给卖方这个动作或这笔钱。常见流程：30% deposit（第 3 期定金）by T/T after contract signing，70% balance before shipment（第 6 期发货前付余款）。实务要点：务必让客户付款后发 remittance advice / bank slip（汇款水单），否则银行到账前你无法确认；跨境汇款通常 1–3 个工作日到账，遇到中转行还要扣手续费（对应已学的 letter of credit 第 8 期信用证、proforma invoice 第 4 期形式发票）。", "collocation": "remittance 汇款；remittance advice 汇款通知/水单；T/T remittance 电汇；send a remittance 汇款；outward / inward remittance 汇出/汇入款；remittance bank 汇款行；remit payment 汇款付款；balance remittance 尾款汇款；remittance fee 汇款手续费", "examples": [{"en": "Please send us the remittance advice once you have transferred the deposit, so we can arrange production immediately.", "zh": "您汇出定金后请把汇款水单发给我们，我们好立刻安排生产。", "audio": "audio/ex/remittance-1.mp3"}], "mnemonic": "re-（回、向后）+ mit（送、放，同根词 submit 提交、permit 许可、transmit 传送）+ -ance = \"把钱送过去\" → 汇款。一串同根词一次记住：remit（汇款）、submit（提交图纸）、transmit（传送文件）、permit（许可）。外贸金句：We will start fabrication upon receipt of your remittance.（收到贵司汇款后即开始加工。）——这句话在催款邮件里既礼貌又专业。", "issue": 19, "date": "2026-09-22", "theme": "柱底垫铁调平找正 → 室内隔断与空间划分 → 客户 T/T 汇款到账 → 指定项目联络人对接 → 赶图旺季警惕职业倦怠", "gloss": "汇款；汇付", "category": "外贸", "audio": "audio/remittance.mp3"}, {"word": "liaison", "phonetic": "/liˈeɪzɑːn/", "meaning": "在两方之间负责沟通协调的人或这种关系，是外贸和项目管理里的\"桥梁\"岗位。典型说法：I'll be your liaison for this project（我是这个项目的对接人）；act as liaison between the design team and the client（在设计团队与客户之间做协调）。它比 contact person 更正式，强调\"持续双向沟通\"而非\"给个号码\"。注意发音 /liˈeɪzɑːn/，来自法语，结尾 n 是鼻音、t 不发音，别读成\"来森\"。和已学的 rapport（第 18 期默契）、follow-up（第 5 期跟进）、briefing（第 15 期简报）配套使用。", "collocation": "liaison 联络/联络人；act as liaison 担任联络人；liaison officer 联络官/对接专员；project liaison 项目联络人；liaise with someone 与某人联络（动词）；close liaison 密切沟通；liaison between A and B 甲乙双方的联络；sales liaison 销售对接", "examples": [{"en": "Our project engineer will act as the liaison between your site team and our drawing office during the whole erection period.", "zh": "在整个安装期间，我们的项目工程师将担任贵方现场团队与我方绘图室之间的联络人。", "audio": "audio/ex/liaison-1.mp3"}], "mnemonic": "法语借词，原意\"连接、结合\"，和 ligament（韧带）、liaise（联络）同根——韧带把骨头连起来，liaison 把两方连起来。客户来访时万能一句：I'll be your liaison — just call me any time.（我是您的对接人，随时找我。）比 \"I'm your contact\" 更显专业和担当，尤其在中东、非洲项目里，客户最看重\"有事能找到人\"。", "issue": 19, "date": "2026-09-22", "theme": "柱底垫铁调平找正 → 室内隔断与空间划分 → 客户 T/T 汇款到账 → 指定项目联络人对接 → 赶图旺季警惕职业倦怠", "gloss": "联络；联络人", "category": "客户接待", "audio": "audio/liaison.mp3"}, {"word": "burnout", "phonetic": "/ˈbɜːrnaʊt/", "meaning": "长期高强度工作导致的身心耗竭状态——不是普通的累（tired），而是\"情绪耗尽 + 效率崩塌 + 对工作失去意义感\"三合一。世界卫生组织已将其列为\"职业现象\"。常与已经学过的 overtime（第 6 期加班）、deadline（第 12 期截止日期）、workload（第 3 期工作量）、stress（压力）连用。动词短语：burn out（累垮）；形容词 burnt-out / burned-out（精疲力竭的）。它也指设备\"烧坏\"，比如 motor burnout（电机烧毁），工程场景同样用得上。", "collocation": "burnout 职业倦怠；suffer from burnout 患上职业倦怠；avoid burnout 避免倦怠；burnout prevention 倦怠预防；on the verge of burnout 濒临倦怠；burnt-out employee 倦怠的员工；combating burnout 对抗倦怠；take a break to prevent burnout 休息一下以防倦怠", "examples": [{"en": "After three months of overtime on the overseas project, he was on the verge of burnout and had to take a short break.", "zh": "在这个海外项目上加班三个月后，他濒临职业倦怠，不得不短暂休息一下。", "audio": "audio/ex/burnout-1.mp3"}], "mnemonic": "burn（燃烧）+ out（尽）= 烧光了 → 像一根蜡烛两头烧，油尽灯枯。区分三个词：tired（累了，睡一觉就好）、stressed（压力大，但还能扛）、burnout（烧干了，需要系统性调整）。职场自救三件套：set boundaries（设边界）、delegate（第 14 期授权分派）、take real time off（真正休假）。今天背完这 5 个词，也算给自己按下一次小小的 reset。", "issue": 19, "date": "2026-09-22", "theme": "柱底垫铁调平找正 → 室内隔断与空间划分 → 客户 T/T 汇款到账 → 指定项目联络人对接 → 赶图旺季警惕职业倦怠", "gloss": "职业倦怠；耗尽", "category": "职场生活", "audio": "audio/burnout.mp3"}, {"word": "parapet", "phonetic": "/ˈpærəpɪt/", "meaning": "屋面、阳台、桥梁边缘向上翻起的那道矮墙，作用是防护、挡水和立面收边。钢结构厂房里常见的是屋面四周 600–1200 mm 高的 parapet，一般由 cladding（第 10 期围护板）上翻或砌块加混凝土压顶（coping）构成。它和已学的 canopy（第 16 期雨棚）、cladding、drainage（第 14 期排水）是同一套\"屋面节点\"词汇——女儿墙内侧必须做好防水收头和排水口，否则雨水倒灌进板缝。建筑史里 parapet 原指城墙上的防护矮墙，词源就是\"护胸\"。", "collocation": "parapet 女儿墙/护墙；parapet wall 女儿墙；parapet height 女儿墙高度；parapet flashing 女儿墙泛水；parapet coping 女儿墙压顶；roof parapet 屋面女儿墙；parapet gutter 女儿墙天沟；parapet panel 女儿墙板", "examples": [{"en": "The roof parapet should be at least 1100 mm high to meet the local safety code for rooftop maintenance access.", "zh": "为满足当地上屋面检修的安全规范，女儿墙高度应不小于 1100 毫米。", "audio": "audio/ex/parapet-1.mp3"}], "mnemonic": "para-（防护，同 parachute 降落伞、parasol 太阳伞）+ pet（= chest 胸，同 pectoral 胸部的）= \"齐胸高的防护墙\" → 女儿墙。画面记忆：站在屋面上，前面那道刚好到胸口、让你不至于掉下去的矮墙。现场高频句：Parapet flashing is missing here.（这里女儿墙泛水没做。）——海外验厂时业主最爱挑这种收边细节，说中它，专业形象立刻建立。", "issue": 20, "date": "2026-09-23", "theme": "屋面临边女儿墙收边 → 板缝打胶防水密封 → 中庭采光空间汇报 → 合同争议仲裁条款 → 项目受挫后快速恢复的韧性", "gloss": "女儿墙；护墙", "category": "建筑设计", "audio": "audio/parapet.mp3"}, {"word": "sealant", "phonetic": "/ˈsiːlənt/", "meaning": "用于封堵板缝、接缝、螺栓孔、窗框周边的材料，钢结构建筑里主要指硅酮（silicone）、聚氨酯（polyurethane）类密封胶，作用是防水、防气渗、允许一定的位移变形。它是 cladding（围护板）、skylight（第 13 期天窗）、curtain wall 幕墙系统的\"最后一道防线\"。动词 seal（密封）+ -ant（表示\"剂、物\"的后缀）。注意区分三个容易混的词：sealant 密封胶（软的、打胶枪打的）、gasket 密封垫（成品垫圈）、grout（第 16 期灌浆料，硬的、浇筑的）。", "collocation": "sealant 密封胶；silicone sealant 硅酮密封胶；apply sealant 打密封胶；sealant joint 密封胶缝；weatherproof sealant 耐候密封胶；sealant gun 打胶枪；polyurethane sealant 聚氨酯密封胶；sealant failure 密封胶失效", "examples": [{"en": "Please apply a weatherproof silicone sealant along all roof panel laps to prevent water ingress during the rainy season.", "zh": "请在所有屋面板搭接处打一道耐候硅酮密封胶，防止雨季渗水。", "audio": "audio/ex/sealant-1.mp3"}], "mnemonic": "seal（密封）+ -ant（剂）= \"用来封缝的东西\" → 密封胶。一个 seal 词根串起一串词：seal（密封）、sealed（已封闭的）、sealant（密封胶）、seam（接缝）。非洲、东南亚客户投诉最多的就是漏水，邮件里这句能救场：The leak is due to sealant failure, not a panel defect.（漏水是密封胶失效，不是板材缺陷。）——一句话厘清责任，避免整批板被索赔（claim 第 13 期）。", "issue": 20, "date": "2026-09-23", "theme": "屋面临边女儿墙收边 → 板缝打胶防水密封 → 中庭采光空间汇报 → 合同争议仲裁条款 → 项目受挫后快速恢复的韧性", "gloss": "密封胶", "category": "工程", "audio": "audio/sealant.mp3"}, {"word": "atrium", "phonetic": "/ˈeɪtriəm/", "meaning": "建筑内部多层通高、通常带玻璃顶的中央空间，常见于酒店、办公楼、商业综合体，作用是引入自然光、组织人流（circulation 第 18 期动线）并提升空间品质。复数是 atriums 或 atria。它和已学的 skylight（第 13 期天窗）、mezzanine（第 14 期夹层）、partition（第 19 期隔断）、circulation（流线）是一组完整的\"内部空间\"词汇。词源是古罗马住宅的中央庭院，现代建筑里复活了这个概念。做方案汇报时，atrium 是提升方案说服力的关键词之一。", "collocation": "atrium 中庭；central atrium 中央中庭；atrium roof 中庭屋盖；glass-roofed atrium 玻璃顶中庭；atrium space 中庭空间；open-air atrium 开敞中庭；atrium lighting 中庭采光；atrium lobby 中庭大堂", "examples": [{"en": "The client loves the central atrium because it brings daylight into the middle of the office floors and cuts lighting costs.", "zh": "客户很喜欢中央中庭，因为它把自然光引入办公区核心，还能降低照明能耗。", "audio": "audio/ex/atrium-1.mp3"}], "mnemonic": "拉丁语 atrium 原指古罗马住宅\"被熏黑的中庭\"（ater = 黑色，因为早期中庭有炉灶）。现代中庭的顶部通常就是一整片 skylight——把第 13 期的天窗架在一个通高空间上方，就是 atrium。方案汇报金句：The atrium acts as the social heart of the building.（中庭是建筑的社交心脏。）比干巴巴地讲\"中间有个大空间\"高级得多。", "issue": 20, "date": "2026-09-23", "theme": "屋面临边女儿墙收边 → 板缝打胶防水密封 → 中庭采光空间汇报 → 合同争议仲裁条款 → 项目受挫后快速恢复的韧性", "gloss": "中庭；采光大厅", "category": "建筑设计", "audio": "audio/atrium.mp3"}, {"word": "arbitration", "phonetic": "/ˌɑːrbɪˈtreɪʃn/", "meaning": "合同双方把争议交给中立第三方（仲裁机构/仲裁员）裁决的纠纷解决方式，裁决结果通常一裁终局、对双方有约束力。外贸合同里几乎必写的条款：Any dispute shall be settled by arbitration in Singapore / Hong Kong, China, under the ICC Rules（争议提交新加坡/中国香港仲裁，适用 ICC 规则）。它比诉讼（litigation）更私密、更快、跨国执行也更容易——因为《纽约公约》让仲裁裁决在 170 多个国家可被执行。和已学的 force majeure（第 18 期不可抗力）、claim（第 13 期索赔）、negotiation（第 11 期谈判）构成完整的\"争议处理链\"：negotiation（谈）→ mediation（调解）→ arbitration（仲裁）→ litigation（诉讼）。", "collocation": "arbitration 仲裁；arbitration clause 仲裁条款；go to arbitration 提交仲裁；arbitration tribunal 仲裁庭；ICC arbitration 国际商会仲裁；arbitration award 仲裁裁决；arbitration seat 仲裁地；binding arbitration 有约束力的仲裁；file for arbitration 申请仲裁", "examples": [{"en": "If we cannot settle the quality dispute through negotiation, the contract allows either party to file for arbitration in Singapore.", "zh": "如果质量争议无法通过协商解决，合同允许任何一方向新加坡申请仲裁。", "audio": "audio/ex/arbitration-1.mp3"}], "mnemonic": "arbiter / arbitrator = 裁判者（联想 arbiter 与 arbitrary 同源，但 arbitrator 是\"中立裁判\"而非\"随心所欲\"）。构词：arbitr-（判断）+ -ation。谈判桌上不必怕提仲裁，这句话既专业又不失礼：We'd prefer to resolve this amicably, but the arbitration clause is there to protect both sides.（我们更希望友好解决，但仲裁条款是为了保护双方。）——先给台阶，再亮底牌。", "issue": 20, "date": "2026-09-23", "theme": "屋面临边女儿墙收边 → 板缝打胶防水密封 → 中庭采光空间汇报 → 合同争议仲裁条款 → 项目受挫后快速恢复的韧性", "gloss": "仲裁", "category": "外贸", "audio": "audio/arbitration.mp3"}, {"word": "resilience", "phonetic": "/rɪˈzɪliəns/", "meaning": "双重身份词——工程里指材料或结构受力变形后恢复原状的能力（elastic resilience 弹性回弹），职场和心理层面指遭遇挫折、失败、高压后快速恢复状态的能力（emotional / professional resilience）。形容词 resilient（有韧性的）。钢结构本身就以 ductility（延性）和 resilience 著称：地震时结构可以变形吸能而不倒塌，这正是抗震设计的核心思路。职场层面则和已学的 burnout（第 19 期职业倦怠）、workload（第 3 期工作量）、stress（压力）配套——resilience 是 burnout 的解药。", "collocation": "resilience 韧性/恢复力；structural resilience 结构韧性；build resilience 培养韧性；resilient design 韧性设计；seismic resilience 抗震韧性；emotional resilience 情绪韧性；show resilience 表现出韧性；resilient material 弹性材料；supply chain resilience 供应链韧性", "examples": [{"en": "Good project managers build resilience by planning buffers into every schedule instead of assuming everything will go smoothly.", "zh": "优秀的项目经理通过在每个进度计划中预留缓冲来建立韧性，而不是假设一切都会顺利。", "audio": "audio/ex/resilience-1.mp3"}], "mnemonic": "re-（回）+ sil-（跳，同根词 salute 致敬、result 结果中都含\"跃动\"概念；也可直记 resilient = \"能弹回来的\"）= 被压下去还能弹回来 → 韧性。一句话双关：A resilient structure bounces back after an earthquake; a resilient person bounces back after a setback.（有韧性的结构在地震后回弹，有韧性的人在挫折后爬起。）这个词既能写进技术报告，也能写进周报自评，性价比极高。", "issue": 20, "date": "2026-09-23", "theme": "屋面临边女儿墙收边 → 板缝打胶防水密封 → 中庭采光空间汇报 → 合同争议仲裁条款 → 项目受挫后快速恢复的韧性", "gloss": "韧性；恢复力", "category": "职场", "audio": "audio/resilience.mp3"}, {"word": "web", "phonetic": "/web/", "meaning": "H 型钢、工字钢截面中连接上下两块 flange（第 5 期翼缘）的那块竖向钢板，主要承受 shear（第 15 期剪力），是截面抗剪的\"腰\"。截面标注 H400×200×8×13 里，8 mm 就是 web thickness（腹板厚），13 mm 是 flange thickness（翼缘厚）。腹板太薄会在支座处发生 web buckling（腹板屈曲），所以集中荷载处要加设 stiffener（第 7 期加劲肋）——第 7 期学的加劲肋，正是焊在腹板两侧的。注意：日常英语里 web 更常指\"网络\"，工程语境下默认指腹板，必要时说 beam web 或 web plate 更保险。", "collocation": "web 腹板；web thickness 腹板厚度；web plate 腹板板件；beam web 梁腹板；web buckling 腹板屈曲；web crippling 腹板压溃；web opening 腹板开孔；web stiffener 腹板加劲肋；web depth 腹板高度", "examples": [{"en": "The beam web is only 8 mm thick, so we need to add bearing stiffeners at both supports.", "zh": "这根梁的腹板只有 8 毫米厚，所以两端支座处需要加设承压加劲肋。", "audio": "audio/ex/web-1.mp3"}], "mnemonic": "一口 H 型钢就是一个\"工\"字——上下两横是 flange（翼缘），中间一竖就是 web（腹板）。联想：web 是蜘蛛网（spider web）那种\"薄薄一片、连着两边\"的东西，腹板正是这样薄薄一片夹在翼缘中间。现场与老外对图时这句很顶用：The web opening here will weaken the section.（这里的腹板开孔会削弱截面。）——专业度立刻拉满。", "issue": 21, "date": "2026-09-24", "theme": "钢结构 H 型钢腹板验算 → 无障碍坡道收方案 → 深化加工图送审 → 报 FOB 离岸价 → 接机路上寒暄破冰", "gloss": "腹板；型钢竖向中间板", "category": "钢结构", "audio": "audio/web.mp3"}, {"word": "ramp", "phonetic": "/ræmp/", "meaning": "连接两个不同标高的倾斜通道，取代或补充 staircase（第 7 期楼梯）。建筑设计里最重要的用法是无障碍坡道：按通行规范，轮椅坡道坡度通常不大于 1:12（每 1 米高差需 12 米水平长度），两侧设扶手、平台设 rest platform。工业厂房里还有 loading ramp（装卸坡道/登车桥）、工地临时 access ramp；公路上 off-ramp / on-ramp 就是匝道。它和已学的 circulation（第 18 期流线）、threshold、handover 配套——无障碍设计是海外公建项目报批的硬指标，很多非洲、中东业主审图第一眼就看坡道做没做。", "collocation": "ramp 坡道；access ramp 无障碍坡道；wheelchair ramp 轮椅坡道；loading ramp 装卸坡道；ramp slope 坡道坡度；ramp gradient 坡道坡度；1:12 ramp 1:12 坡道；off-ramp 出口匝道；ramp handrail 坡道扶手", "examples": [{"en": "The main entrance needs a wheelchair ramp with a maximum gradient of 1:12 and handrails on both sides.", "zh": "主入口需要设置轮椅坡道，最大坡度 1:12，两侧设扶手。", "audio": "audio/ex/ramp-1.mp3"}], "mnemonic": "ramp 谐音\"软坡\"——不是硬邦邦的台阶，而是\"软下来\"的一段斜面。词根联想：ramp 与 climb、scramble 都有\"爬、攀\"的语感。报批汇报金句：The ramp is part of the accessible circulation, not an afterthought.（坡道是无障碍流线的一部分，不是事后补的。）——把无障碍设计说成\"系统性考虑\"，业主与审批方都会认可。", "issue": 21, "date": "2026-09-24", "theme": "钢结构 H 型钢腹板验算 → 无障碍坡道收方案 → 深化加工图送审 → 报 FOB 离岸价 → 接机路上寒暄破冰", "gloss": "坡道；无障碍斜坡", "category": "建筑设计", "audio": "audio/ramp.mp3"}, {"word": "shop drawing", "phonetic": "/ˈʃɒp ˈdrɔːɪŋ/", "meaning": "由加工方/承包商在施工图（blueprint 第 9 期蓝图、施工图）基础上细化出的、可直接下料生产的图纸，包含每个构件的 exact 尺寸、孔位、坡口、焊缝等级、螺栓规格与材料表（BOM）。流程上是：design drawing（设计院出图）→ shop drawing（我方深化）→ approval（业主/顾问审批）→ fabrication（第 1 期加工制造）。海外项目几乎都要求 shop drawing for approval 先批再生产，这是控制索赔（claim 第 13 期）风险的关键关口——图纸没批就下料，改一次就是一整批构件报废。", "collocation": "shop drawing 加工图/深化图；shop drawing for approval 送审加工图；submit shop drawings 提交加工图；approved shop drawing 已批准的加工图；shop drawing revision 加工图升版；as-built drawing 竣工图；fabrication drawing 制作图；drawing register 图纸台账", "examples": [{"en": "We will submit the shop drawings for your approval before we start cutting any material.", "zh": "我们会在开始下料之前提交加工图供贵方审批。", "audio": "audio/ex/shop-drawing-1.mp3"}], "mnemonic": "shop 不是\"商店\"，是 workshop / fabrication shop（加工车间）——\"车间里用的图\"就是 shop drawing。串起一条完整图纸链：design drawing（设计图）→ shop drawing（深化加工图）→ as-built drawing（竣工图）。外贸邮件里这句能护住自己：Production will start upon receipt of approved shop drawings.（收到批准的加工图后即开始生产。）——既表诚意，又把工期责任划清楚。", "issue": 21, "date": "2026-09-24", "theme": "钢结构 H 型钢腹板验算 → 无障碍坡道收方案 → 深化加工图送审 → 报 FOB 离岸价 → 接机路上寒暄破冰", "gloss": "加工图；深化设计图", "category": "工程设计", "audio": "audio/shop-drawing.mp3"}, {"word": "FOB", "phonetic": "/ˌef əʊ ˈbiː/", "meaning": "Incoterms 国际贸易术语之一，全称 Free On Board（…named port of shipment），指卖方把货物装上买方指定船只即完成交货，此前的费用与风险归卖方，装船后（越过船舷/装上船）的风险与运费归买方。外贸报价最常用三兄弟：EXW（工厂交货，卖方责任最小）、FOB（离岸价，最常用）、CIF（成本加保险费加运费，卖方责任更大）。报价单上要写全\"FOB Qingdao\"而不是只写 FOB——港口没写清，后面 freight（第 5 期运费）扯皮是常态。它和已学的 quotation（第 1 期报价）、proforma invoice（第 4 期形式发票）、bill of lading（第 9 期提单）、customs clearance（第 7 期清关）构成完整成交链。", "collocation": "FOB 离岸价；FOB Qingdao 青岛离岸价；FOB price 离岸价；FOB terms FOB 条款；FOB shipment FOB 装运；EXW 工厂交货；CIF 到岸价；Incoterms 2020 国际贸易术语解释通则；FOB value 离岸价金额", "examples": [{"en": "Our quotation is USD 1,150 per ton FOB Qingdao, valid for 30 days.", "zh": "我们的报价是每吨 1150 美元，青岛离岸价，有效期 30 天。", "audio": "audio/ex/fob-1.mp3"}], "mnemonic": "拆开记 F-O-B = Free On Board，\"货一上船（on board），卖方就 free（解脱）了\"——责任和费用到此为止。三个术语用一句话分清：EXW 出门不管，FOB 装上船不管，CIF 送到对方港才不管。报价电话里标准话术：The price is FOB Qingdao, excluding inland haulage to the port.（价格是青岛离岸价，不含到港的内陆运输。）——把边界说清，后面少一半麻烦。", "issue": 21, "date": "2026-09-24", "theme": "钢结构 H 型钢腹板验算 → 无障碍坡道收方案 → 深化加工图送审 → 报 FOB 离岸价 → 接机路上寒暄破冰", "gloss": "离岸价（FOB）", "category": "外贸", "audio": "audio/fob.mp3"}, {"word": "small talk", "phonetic": "/ˈsmɔːl tɔːk/", "meaning": "正式会议开始前、接机路上、茶歇时那些不涉及业务的轻松对话——天气、航班、当地美食、足球、家庭。它看着没用，实际是客户接待（hospitality 第 3 期礼遇）里最重要的软技能：先 small talk 建立 rapport（第 18 期融洽关系），再进 negotiation（第 11 期谈判），成交概率完全不同。安全话题：travel、food、sports、local scenery；雷区：religion、politics、personal income。对中东、非洲客户，先问候家人与健康是标准礼节；对欧美客户，聊行程与体育更稳妥。", "collocation": "small talk 寒暄/闲聊；make small talk 寒暄几句；engage in small talk 进行闲聊；break the ice 破冰；safe topics 安全话题；weather small talk 聊天气；small talk skills 寒暄技巧；wrap up the small talk 结束寒暄转入正题", "examples": [{"en": "We made small talk about his flight and the local food on the way from the airport, and the meeting started in a relaxed mood.", "zh": "从机场出来的路上我们聊了他的航班和当地美食，会议因此在一个轻松的氛围中开始。", "audio": "audio/ex/small-talk-1.mp3"}], "mnemonic": "small = 小事，talk = 说话 → \"说点小事\"。它不是废话，是把 rapport（第 18 期）这台机器预热的火柴。万能开场三句：How was your flight?（航班还顺利吗？）/ Is this your first time in Qingdao?（第一次来青岛吗？）/ Have you tried the local seafood yet?（尝过本地海鲜了吗？）接机路上用完这三句，再进会议室，气氛就完全不一样了。", "issue": 21, "date": "2026-09-24", "theme": "钢结构 H 型钢腹板验算 → 无障碍坡道收方案 → 深化加工图送审 → 报 FOB 离岸价 → 接机路上寒暄破冰", "gloss": "寒暄；闲聊破冰", "category": "客户接待", "audio": "audio/small-talk.mp3"}]};
